export interface AASQuestion {
  question: string
  options: string[]
  correctAnswer: number
  explanation: string
  difficulty: 'easy' | 'medium' | 'hard'
  domain: string
  topicSlug: string
  formSet: number
  /** Lesson part (1–7) that teaches this item. */
  part?: number
}

export const aasQuestionPool: AASQuestion[] = [
  // ════════════════ Unit 1 — origins-diaspora ════════════════

  // ── aas-african-kingdoms ──
  { question: 'Which exchange formed the core of the trans-Saharan caravan trade that enriched Ghana and Mali?', options: ['West African gold traded for desert salt', 'East African ivory traded for Indian cloth', 'Kongo copper traded for Portuguese firearms', 'Swahili spices traded for Chinese porcelain'], correctAnswer: 0, explanation: 'Camel caravans carried West African gold north and brought Saharan salt south, and taxing that exchange underwrote Ghana and then Mali. Ivory-for-cloth and spice exchanges belong to the Indian Ocean trade of the East African coast, and Kongo\'s dealings with Portugal were an Atlantic connection, not a trans-Saharan one.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 1, formSet: 1 },
  { question: 'Sundiata Keita (r. c. 1235–1255) is remembered in West African history chiefly as the ruler who', options: ['founded Songhai by seizing Timbuktu and Djenné', 'founded Mali after defeating Sosso at Kirina', 'united Kongo after converting to Catholicism', 'built the stone capital at Great Zimbabwe'], correctAnswer: 1, explanation: 'Sundiata defeated Sumanguru of Sosso at the Battle of Kirina (1235) and founded the Mali Empire, a story preserved in the Epic of Sundiata. Seizing Timbuktu and Djenné was the work of the Songhai ruler Sunni Ali, Kongo\'s Catholic king was Afonso I, and Great Zimbabwe lay far to the southeast.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 1, formSet: 2 },
  { question: 'Accounts of Mansa Musa\'s 1324 pilgrimage to Mecca report that his caravan spent and gave away so much gold in Egypt\'s capital that', options: ['Egypt\'s rulers barred West African merchants from their markets', 'the sultan of Morocco launched an invasion to seize Mali\'s mines', 'the value of gold in Cairo fell and stayed depressed for years', 'Mali\'s court adopted Islam as its official religion upon his return'], correctAnswer: 2, explanation: 'Musa\'s lavish spending flooded Cairo with gold and depressed its value for about a decade, and the pilgrimage placed Mali on European maps. Mali\'s rulers were already Muslim before the hajj, the Moroccan invasion came in 1591 against Songhai, and Egypt did not bar West African traders.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 1, formSet: 1 },
  { question: 'How did trans-Saharan trade help make Timbuktu and Djenné centers of Islamic scholarship?', options: ['Portuguese missionaries opened schools along the caravan routes', 'Moroccan conquerors imposed Islamic law after the fall of Songhai', 'Swahili merchants carried Quranic learning across from the east coast', 'Muslim teachers arrived with the caravans and rulers funded them'], correctAnswer: 3, explanation: 'Caravans carried Muslim merchants, scholars, and books across the Sahara, and rulers such as Mansa Musa and Askia Muhammad patronized mosques and the Sankore Madrasa. Portuguese missionaries worked on the Atlantic coast, the Moroccan conquest of 1591 came after these centers were already established, and Swahili traders worked the Indian Ocean coast.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 2, formSet: 2 },
  { question: 'The Ghana Empire (c. 300–1076) drew most of its wealth and power from', options: ['taxing the gold and salt that passed through its territory', 'exporting enslaved captives to Portuguese ships on the coast', 'shipping ivory to Indian Ocean ports through Kilwa and Sofala', 'growing cotton on royal estates worked by conquered peoples'], correctAnswer: 0, explanation: 'Ghana controlled and taxed the gold–salt trade that crossed its lands until the Almoravids sacked it in 1076. The Portuguese did not reach West Africa until the 1440s, long after Ghana\'s fall, and the ivory routes through Kilwa and Sofala belonged to East Africa.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 2, formSet: 1 },
  { question: 'Sunni Ali\'s capture of Timbuktu (1468) and Djenné (1473) mattered for West African history mainly because it', options: ['ended Songhai\'s independence and opened the region to Moroccan rule', 'placed the region\'s chief trade and scholarly cities under Songhai rule', 'linked the Swahili coast to the gold fields of the West African interior', 'gave Portugal its first trading posts in the interior of West Africa'], correctAnswer: 1, explanation: 'Sunni Ali built Songhai\'s army and seized the great commercial and scholarly cities, setting up the centralized empire that Askia Muhammad later organized. Songhai\'s fall to Morocco came at Tondibi in 1591, more than a century later, and these conquests had nothing to do with the Swahili coast or Portuguese posts.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 2, formSet: 2 },
  { question: 'Which statement describes a valid similarity between Great Zimbabwe and the Mali Empire?', options: ['Both fell to Moroccan musketeers at the end of the sixteenth century.', 'Both adopted Catholicism through alliances with Portuguese traders.', 'Both drew wealth from controlling long-distance trade in gold.', 'Both used Swahili as the language of their royal courts.'], correctAnswer: 2, explanation: 'Great Zimbabwe controlled gold and ivory routes to the coast at Sofala, while Mali taxed the trans-Saharan gold trade, so both rested on long-distance gold commerce. Morocco defeated Songhai, not either of these states, Catholic conversion describes Kongo, and Swahili developed in the coastal city-states.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 3, formSet: 1 },
  { question: 'Kilwa, Mombasa, and Mogadishu (c. 800–1500) grew wealthy as part of which network?', options: ['The trans-Saharan caravan trade', 'The Atlantic triangular trade', 'The Mediterranean galley trade', 'The Indian Ocean maritime trade'], correctAnswer: 3, explanation: 'The Swahili city-states linked the East African coast to Indian Ocean commerce, and the Swahili language emerged from that contact. Trans-Saharan caravans served West Africa, the Atlantic trade began only after the Portuguese voyages of the 1400s, and these ports did not trade by Mediterranean galley.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 3, formSet: 2 },
  { question: 'Why does an AP African American Studies course begin with the kingdoms of West and Central Africa?', options: ['People later forced into the Atlantic trade came from these societies and kept their traditions.', 'Mali\'s emperors organized and directed the Atlantic slave trade from its start in the 1400s.', 'These states had collapsed before 1500, which left the coast open to European colonization.', 'Their Islamic legal codes became the model that colonial assemblies used for slave law.'], correctAnswer: 0, explanation: 'The course treats these societies as the homelands of the diaspora: later forced migrations scattered their people, who carried memories and practices to the Americas. Mali had declined before the Atlantic trade grew, states such as Kongo and Songhai still stood in 1500, and colonial slave codes drew on English, not Islamic, law.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 4, formSet: 1 },
  { question: 'Mansa Musa\'s pilgrimage placed Mali on European maps in the 1300s. Which later development does that fame help explain?', options: ['Spain\'s decision to send the first enslaved Africans to Virginia', 'Portugal\'s voyages down the African coast in search of gold', 'England\'s chartering of the Royal African Company in 1672', 'Morocco\'s alliance with Mali against the Songhai Empire'], correctAnswer: 1, explanation: 'European awareness of West African gold helped draw Portuguese ships down the coast in the 1400s, the voyages that opened the Atlantic trade. The 1619 arrival in Virginia came on an English privateer, the Royal African Company was an English monopoly formed centuries later, and Morocco attacked Songhai rather than allying with Mali.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 4, formSet: 2 },
  { question: 'The Battle of Tondibi (1591) is a turning point in West African history because', options: ['Sundiata\'s cavalry broke the power of the Sosso kingdom', 'Almoravid armies sacked the capital of the Ghana Empire', 'Moroccan musketeers defeated Songhai\'s cavalry and ended the empire', 'Portuguese ships first landed captives at the port of Lagos'], correctAnswer: 2, explanation: 'At Tondibi, Moroccan troops armed with firearms crushed Songhai\'s cavalry, ending West Africa\'s last great trans-Saharan empire. Sundiata\'s victory over the Sosso was at Kirina in 1235, the Almoravids sacked Ghana in 1076, and the Lagos auction of 1444 was in Portugal.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 5, formSet: 1 },
  { question: 'Which development on the East African coast between c. 800 and 1500 best shows long-distance trade producing a new, blended culture?', options: ['Askia Muhammad\'s support for the scholars at the Sankore Madrasa', 'The collapse of Songhai power after the Battle of Tondibi', 'The growth of the gold–salt trade through the Ghana Empire', 'The rise of the Swahili language in Kilwa and other port towns'], correctAnswer: 3, explanation: 'Swahili emerged in Kilwa, Mombasa, and other coastal towns as African communities traded with Indian Ocean merchants, a clear example of cultural blending through commerce. The other choices are West African developments, and the fall of Songhai marks political collapse rather than cultural synthesis.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 5, formSet: 2 },
  { question: 'Read the excerpt, adapted from Ibn Battuta\'s Rihla (1355), describing Mali in 1352–1354: "They are seldom unjust, and the sultan shows no mercy to anyone guilty of the least act of injustice. There is complete security in their country." The passage is most useful as evidence of', options: ['a strong royal government keeping order across Mali\'s roads', 'Songhai\'s military conquest of Timbuktu and the cities of the Niger', 'Portuguese influence on the law courts of the West African interior', 'Mali\'s decline after Moroccan troops defeated its army in battle'], correctAnswer: 0, explanation: 'Ibn Battuta, a Moroccan jurist who visited the court of Mansa Suleyman, describes justice and security enforced by the ruler, evidence of centralized royal authority. Songhai\'s conquests came a century later, the Portuguese had no role in Mali\'s courts, and Morocco\'s 1591 invasion struck Songhai, not Mali at its height.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 6, formSet: 1 },
  { question: 'Read the excerpt, adapted from a 1526 letter by King Afonso I of Kongo to King João III of Portugal: "Each day the traders are kidnapping our people, even nobles and members of our own family, and our land is being depopulated." The letter is best used as evidence that', options: ['Kongo\'s king rejected Christianity and expelled the Portuguese priests', 'Kongo\'s king sought to curb Portuguese slaving that harmed his realm', 'Kongo\'s merchants controlled the caravan routes across the Sahara', 'Kongo\'s king asked Portugal for troops to help him conquer Songhai'], correctAnswer: 1, explanation: 'Afonso I, a Catholic convert, wrote to Portugal\'s king to protest the slave raiding that was destabilizing Kongo. He did not reject Christianity, Kongo lay in Central Africa far from the Sahara, and the letter says nothing about Songhai.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 6, formSet: 2 },
  { question: 'A historian using the Epic of Sundiata as evidence about the founding of Mali should account for which feature of the source?', options: ['A Moroccan traveler wrote it after a single brief visit to the court.', 'Portuguese merchants composed it to justify their trade with Mali.', 'Griots passed it down orally to honor and preserve Mali\'s origins.', 'Scholars of Songhai wrote it down as a chronicle of their rulers.'], correctAnswer: 2, explanation: 'The Epic is an oral tradition kept by Mande griots, so its purpose of honoring Sundiata shapes what it emphasizes. The Moroccan traveler is Ibn Battuta, whose Rihla is a different source, and the Songhai chronicle is the Tarikh al-Sudan; Portuguese merchants had no role in it.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 6, formSet: 1 },
  { question: 'A student essay credits a West African ruler with centralizing the empire\'s administration, making his own pilgrimage to Mecca, and raising the Sankore Madrasa to new prominence. Which ruler fits that description?', options: ['Sunni Ali', 'Mansa Musa', 'Sundiata Keita', 'Askia Muhammad'], correctAnswer: 3, explanation: 'Askia Muhammad I (r. 1493–1528) organized Songhai\'s administration, performed a hajj, and elevated Timbuktu\'s Sankore Madrasa. Sunni Ali built Songhai\'s army but is not known for the hajj, Mansa Musa ruled Mali two centuries earlier, and Sundiata founded Mali.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 7, formSet: 2 },
  { question: 'Which pair of evidence best supports the claim that West African states of the Mali and Songhai era were both literate and commercially sophisticated?', options: ['The Tarikh al-Sudan chronicle and Mali\'s taxed caravan trade', 'The Epic of Sundiata and the Battle of Tondibi', 'The Battle of Kirina and the Almoravid sack of Ghana', 'Great Zimbabwe\'s walls and Kongo\'s Catholic conversion'], correctAnswer: 0, explanation: 'A written Timbuktu chronicle shows literacy, and a taxed caravan trade shows commercial organization, so that pair supports both halves of the claim. The other pairs mix an oral epic, battles, building, and religion, none of which shows both literacy and commerce.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 7, formSet: 1 },
  { question: 'The kingdom of Kush, centered in Nubia along the upper Nile, is significant in early African history because its rulers', options: ['adopted Christianity and minted coins for the Red Sea trade', 'conquered Egypt and ruled it as its pharaohs in the 700s BCE', 'founded the trading city-states along the East African coast', 'built stone enclosures to control the gold routes to Sofala'], correctAnswer: 1, explanation: 'Kushite kings conquered Egypt in the eighth century BCE and ruled as its Twenty-fifth Dynasty, and Kush later flourished at Meroë as an iron-working center. Adopting Christianity and minting coins describes Aksum, the coastal city-states were Swahili, and the stone enclosures belong to Great Zimbabwe.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 1, formSet: 1 },
  { question: 'Which description best fits the kingdom of Aksum, in present-day Ethiopia and Eritrea, during the first millennium CE?', options: ['A Sahel empire that taxed the gold and salt of the trans-Saharan routes', 'A Red Sea trading state that minted coins and adopted Christianity', 'A Central African kingdom whose king protested Portuguese slaving', 'A Nile Valley kingdom whose rulers governed Egypt as its pharaohs'], correctAnswer: 1, explanation: 'Aksum grew rich on Red Sea and Indian Ocean trade, issued its own coins, and adopted Christianity under King Ezana in the fourth century. Taxing the gold–salt trade describes Ghana and Mali, the protest against Portuguese slaving came from Kongo, and ruling Egypt as pharaohs describes Kush.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 3, formSet: 2 },
  { question: 'Brass plaques that once decorated the royal palace of Benin, in present-day Nigeria, depict obas (kings), court officials, warriors, and Portuguese visitors. The plaques are most useful to historians as evidence of', options: ['an Islamic scholarly tradition centered on the mosques of Timbuktu', 'a stateless farming society that had no royal court or palace', 'a centralized kingdom whose rulers commissioned art recording their reign', 'a Swahili trading culture shaped by merchants from the Indian Ocean'], correctAnswer: 2, explanation: 'Benin\'s obas commissioned brass plaques and other court art that documented royal power, ceremony, and contact with Portuguese traders, revealing a centralized, wealthy kingdom. Timbuktu\'s scholarship belongs to Mali and Songhai, the plaques themselves show a royal court, and Benin lay in West Africa rather than on the Swahili coast.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-african-kingdoms', part: 3, formSet: 1 },

  // ── aas-origins-diaspora ──
  { question: 'On the South Carolina and Georgia Sea Islands, enslaved Africans and their descendants developed Gullah, a language that pairs mostly English words with West African grammar and sound patterns. Gullah is a clear example of', options: ['assimilation', 'creolization', 'manumission', 'colonization'], correctAnswer: 1, explanation: 'Creolization is the blending of African, European, and Indigenous forms into new languages and cultures, and Gullah fuses English vocabulary with West African structure. Assimilation would mean abandoning African forms entirely, manumission is an owner granting freedom, and colonization refers to settlement schemes or imperial rule.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 1, formSet: 1 },
  { question: 'Which example best illustrates cultural retention, as distinct from creolization, among enslaved people in the Americas?', options: ['Haitian Kreyòl forming from French words and West African grammar', 'Enslaved people adopting English as their only spoken language', 'Planters passing colonial laws that banned drums on plantations', 'Musicians keeping West African call-and-response singing patterns'], correctAnswer: 3, explanation: 'Cultural retention is the survival of an African practice, such as call-and-response singing, in the Americas. Kreyòl is a new blended language and so illustrates creolization, adopting English alone describes assimilation, and laws banning drums are an act of control by planters rather than a Black cultural practice.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 1, formSet: 2 },
  { question: 'In this course, the term "African diaspora" refers most precisely to', options: ['the scattering of African-descended peoples across the Atlantic world and their ongoing ties to Africa', 'the early migrations of Bantu-speaking farmers across central and southern Africa over many centuries', 'the resettlement of freed African Americans in Liberia under the American Colonization Society', 'the system of plantations in the Americas that depended on the labor of enslaved Africans'], correctAnswer: 0, explanation: 'The diaspora is the dispersal of African-descended peoples, mainly through the transatlantic slave trade, together with the cultural connections they kept. Bantu migrations happened within Africa, Liberian resettlement is a single later episode, and the plantation system is the economy that drove the dispersal rather than the diaspora itself.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 1, formSet: 1 },
  { question: 'The 1791 Bois Caïman ceremony led by the Vodou priest Boukman Dutty is significant because it', options: ['ended the First Maroon War through a treaty with Britain', 'helped ignite the Haitian Revolution in Saint-Domingue', 'marked the first sale of African captives in Lisbon', 'founded the first independent Black church in Philadelphia'], correctAnswer: 1, explanation: 'Boukman\'s Vodou ceremony at Bois Caïman bound rebels together and launched the 1791 uprising that became the Haitian Revolution. The maroon treaties came in Jamaica in 1739, the first Lisbon captives arrived in 1441, and the first independent Black denomination grew out of Philadelphia churches decades later.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 1, formSet: 2 },
  { question: 'When England seized Jamaica from Spain in 1655, many people who had been enslaved under Spanish rule', options: ['gained their freedom under English laws that banned slavery', 'fled to the mountains and formed maroon communities there', 'were shipped north to work on tobacco farms in Virginia', 'were sent back to Spain under the terms of a peace treaty'], correctAnswer: 1, explanation: 'During the English takeover, enslaved people escaped into Jamaica\'s mountains and built maroon communities that resisted the British for decades. England had no law banning slavery and soon built a plantation economy on the island, and these people were neither shipped to Virginia nor returned to Spain.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 2, formSet: 1 },
  { question: 'Which event marks the beginning of the European Atlantic slave trade?', options: ['English seizure of Jamaica, 1655', 'Maroon treaties in Jamaica, 1739', 'Captives to Lisbon, 1441', 'Arrival at Point Comfort, 1619'], correctAnswer: 2, explanation: 'Portuguese voyagers brought the first African captives to Lisbon in 1441, beginning European Atlantic slaving. The arrival at Point Comfort in 1619 came nearly two centuries later and marks the first recorded Africans in English North America, while the Jamaica events of 1655 and 1739 shaped the Caribbean diaspora much later.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 2, formSet: 2 },
  { question: 'Which statement accurately contrasts the Portuguese–Kongo slave trade of the 1500s with the 1619 arrival of Africans at Point Comfort, Virginia?', options: ['Kongo shows the trade ending in Central Africa; Point Comfort shows its first arrival anywhere in the Americas.', 'Kongo shows Portugal banning the trade by law; Point Comfort shows England\'s first written law on slavery.', 'Kongo shows Muslim merchants running the trade; Point Comfort shows Dutch rule over the Virginia colony.', 'Kongo shows an African ruler protesting the trade; Point Comfort shows its arrival in English North America.'], correctAnswer: 3, explanation: 'In Kongo, King Afonso I protested Portuguese slaving inside his kingdom, while 1619 marks the first recorded enslaved Africans in English North America. Africans reached Spanish and Portuguese America a century before 1619 and the Kongo trade kept growing, Portugal did not ban the trade, and Virginia was an English colony.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 3, formSet: 1 },
  { question: 'Historians estimate that about 12.5 million Africans were forced aboard ships in the Atlantic slave trade and about 10.7 million survived the crossing. Roughly what share of those embarked died at sea?', options: ['About 3 percent', 'About 14 percent', 'About 40 percent', 'About 86 percent'], correctAnswer: 1, explanation: 'About 1.8 million of 12.5 million people died, roughly 14 percent, in line with the Middle Passage mortality averages historians describe. Eighty-six percent is the share who survived, and the other figures do not match the estimates.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 3, formSet: 2 },
  { question: 'Historians describe Nanny, leader of Jamaica\'s Windward Maroons, as Asante-descended. That detail best supports which claim about the diaspora?', options: ['Maroon communities were founded mostly by escaped European servants.', 'The Asante state directed maroon warfare in Jamaica from West Africa.', 'Captive Africans carried West African traditions to the Americas.', 'Maroons gave up African customs in order to blend into colonial society.'], correctAnswer: 2, explanation: 'Nanny\'s Asante roots show how the diaspora preserved the memory and practices of particular African societies, linking Unit 1\'s states to the Americas. Jamaica\'s maroons were Africans and their descendants, the Asante state did not command them from Africa, and maroons kept rather than abandoned African customs.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 4, formSet: 1 },
  { question: 'The Portuguese–Kongo slave trade of the 1500s ties the African kingdoms of Unit 1 to the later diaspora because it', options: ['pulled captives from an established Central African state into the Atlantic trade', 'brought Islam to Central Africa through Portuguese merchants and their trade', 'ended Kongo as an independent state when Portugal annexed it in the 1500s', 'sent Kongo\'s royal family to Lisbon as captives of the Portuguese crown'], correctAnswer: 0, explanation: 'The trade entangled Kongo, an organized Central African kingdom, so people from that society entered the Atlantic diaspora; Afonso I\'s protests show the kingdom was still functioning. The Portuguese were Catholic, not Muslim, Kongo remained independent through the 1500s, and its royal family was not taken to Lisbon.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 4, formSet: 2 },
  { question: 'The 1739 treaties between Britain and Jamaica\'s maroons marked a change because', options: ['Britain abolished slavery across Jamaica as part of the peace', 'the maroons agreed to leave Jamaica and resettle in West Africa', 'a colonial power formally recognized maroon self-rule', 'the Atlantic slave trade to Jamaica came to a halt for a decade'], correctAnswer: 2, explanation: 'After the First Maroon War, Britain signed treaties recognizing maroon autonomy, an acknowledgment that escaped people had built communities it could not defeat. Slavery continued in Jamaica until British emancipation in the 1830s, the maroons stayed on the island, and the slave trade to Jamaica did not stop in 1739.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 5, formSet: 1 },
  { question: 'A historian argues that the African diaspora between c. 1450 and 1800 shows both continuity and change. Which evidence best supports the CHANGE side of that argument?', options: ['Asante-descended leaders guiding Jamaica\'s maroon communities', 'Enslaved musicians keeping West African call-and-response forms', 'Vodou rituals drawing on West and Central African religion', 'British treaties of 1739 recognizing maroon self-government'], correctAnswer: 3, explanation: 'The 1739 treaties were a new political arrangement in which a colonial power accepted maroon autonomy, so they show change. Asante-descended leadership, call-and-response music, and Vodou\'s African roots all show African traditions persisting, which is continuity.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 5, formSet: 2 },
  { question: 'Phillis Wheatley\'s Poems on Various Subjects (1773) opened with a statement signed by prominent Boston men affirming that she had written the poems herself. That statement suggests the book had to', options: ['answer doubts that an enslaved African could write such verse', 'raise money for the Royal African Company and its trading posts', 'win approval from colonial assemblies that licensed all printers', 'persuade readers that the Middle Passage had been a humane voyage'], correctAnswer: 0, explanation: 'White readers doubted that an enslaved African could write classical verse, so the attestation was needed to establish authorship, and the book itself challenged proslavery claims about Black intellect. It was not a fundraiser for slavers, colonial assemblies did not license the poems, and the volume did not defend the Middle Passage.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 6, formSet: 1 },
  { question: 'Ottobah Cugoano\'s Thoughts and Sentiments on the Evil of Slavery (1787) stood out among British antislavery writings of the 1780s because it', options: ['asked only for better food and space aboard slave ships', 'defended the trade as necessary for Britain\'s sugar colonies', 'urged freed Africans to resettle in the Kingdom of Kongo', 'demanded total abolition and came from a survivor of slavery'], correctAnswer: 3, explanation: 'Cugoano, Fante-born and formerly enslaved, wrote from London demanding the complete end of slavery and the trade, unusual both for its radical demand and for its author\'s experience. Proposals to regulate shipboard conditions were the cautious reforms he went beyond, he attacked rather than defended the trade, and he did not promote resettlement in Kongo.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 6, formSet: 2 },
  { question: 'Olaudah Equiano opens The Interesting Narrative (1789) with a detailed, admiring account of Igbo village life before his capture. He most likely included it in order to', options: ['encourage British readers to settle in the Bight of Biafra region', 'record his capture as evidence for a lawsuit against a ship captain', 'counter the claim that slavery rescued Africans from savage lands', 'show that Portugal controlled the trade in the African interior'], correctAnswer: 2, explanation: 'Writing for British readers during the abolition debate, Equiano presented an ordered, moral Igbo society to undercut the proslavery claim that enslavement improved Africans\' lives. He was not recruiting settlers, the book was not a legal filing, and his account says nothing about Portuguese control of the interior.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 6, formSet: 1 },
  { question: 'Which figure led Jamaica\'s Windward Maroons against British forces in the early 1700s?', options: ['Boukman Dutty', 'Olaudah Equiano', 'Ottobah Cugoano', 'Nanny'], correctAnswer: 3, explanation: 'Nanny, of Asante descent, led the Windward Maroons in their war against the British. Boukman Dutty was a Vodou priest in Saint-Domingue, and Equiano and Cugoano were writers who attacked the slave trade from Britain.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 7, formSet: 2 },
  { question: 'Which source would best support an essay on how enslaved Africans used literacy to challenge proslavery claims in the 1770s?', options: ['Wheatley\'s Poems on Various Subjects, 1773', 'Boukman\'s ceremony at Bois Caïman, 1791', 'The treaties with Jamaica\'s maroons, 1739', 'The first captives landed at Lisbon, 1441'], correctAnswer: 0, explanation: 'Wheatley\'s 1773 volume displayed an enslaved woman\'s classical learning and was read as a direct answer to claims of African inferiority. The Bois Caïman ceremony was a religious and revolutionary act of 1791, the maroon treaties were diplomatic agreements, and the 1441 landing predates the period entirely.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 7, formSet: 1 },
  { question: 'Queen Njinga of Ndongo and Matamba fought Portuguese expansion in the 1600s yet also sold war captives to European traders. Her career best illustrates that', options: ['African states uniformly refused to take any part in the Atlantic trade', 'African rulers both resisted and joined the trade to serve their own aims', 'Portugal had fully conquered all of Central Africa by the early 1600s', 'the Atlantic trade drew captives almost entirely from the West African Sahel'], correctAnswer: 1, explanation: 'Njinga shows that African rulers responded to the Atlantic trade in complex ways, resisting European conquest while sometimes trading captives to strengthen their states. African states did not uniformly refuse to participate, Portugal held only coastal footholds such as Luanda, and West Central Africa was in fact the largest single source region of captives.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-origins-diaspora', part: 2, formSet: 2 },

  // ── aas-transatlantic-slave-trade ──
  { question: 'Of the roughly 10.7 million Africans who survived the Middle Passage between 1501 and 1866, about 388,000 landed in mainland North America. These figures show that', options: ['the great majority landed in British North America', 'the North American mainland took in about half of all survivors', 'most survivors were taken to the Caribbean and South America', 'North America received more captives than Brazil in these years'], correctAnswer: 2, explanation: 'About 388,000 of 10.7 million is roughly 3.6 percent, so the overwhelming majority went to the Caribbean and South America, with Brazil the largest single destination. The figures rule out any claim that mainland North America took most, half, or more than Brazil.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 1, formSet: 1 },
  { question: 'Which sequence correctly traces the three legs of the triangular trade?', options: ['Captives to Europe, manufactures to the Americas, sugar to Africa', 'Sugar to Africa, captives to Europe, manufactures to the Americas', 'Manufactures to the Americas, sugar to Africa, captives to Europe', 'Manufactures to Africa, captives to the Americas, sugar to Europe'], correctAnswer: 3, explanation: 'European manufactured goods went to Africa, African captives were carried across the Atlantic to the Americas, and plantation goods such as sugar returned to Europe. The other sequences send captives to Europe or sugar to Africa, reversing the flows that tied the four continents together.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 1, formSet: 2 },
  { question: 'For much of the 1500s and 1600s, the oba (king) of Benin limited the sale of male captives to Europeans and traded mainly pepper, ivory, and cloth. This policy shows that', options: ['European traders dictated policy to every state on the coast', 'Benin had no dealings at all with Portuguese or Dutch merchants', 'the Atlantic trade began only when Benin\'s rulers requested it', 'some African rulers set the terms of their trade with Europeans'], correctAnswer: 3, explanation: 'Benin\'s obas controlled what they would sell, restricting the export of male captives for long periods while exporting other goods, so African states were not simply at the mercy of European demand. Europeans did not dictate to coastal kingdoms in this era, Benin traded actively with the Portuguese and later the Dutch, and the Atlantic trade began with Portuguese voyages, not at Benin\'s request.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 1, formSet: 1 },
  { question: 'In 1518 the Spanish crown authorized ships to carry captives directly from Africa to its American colonies. This decision changed the trade by', options: ['banning the use of African labor in Spain\'s silver mines', 'giving English merchants control of shipments to the Caribbean', 'limiting the trade to Africans who had converted to Christianity', 'ending the practice of routing them through Iberia first'], correctAnswer: 3, explanation: 'Before 1518 most Africans reached Spanish America by way of Spain and Portugal; direct shipments bypassed that re-export and opened the large-scale Atlantic crossing. Spain did not ban African labor in its mines, England had no control of the trade in 1518, and no conversion requirement limited it.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 2, formSet: 1 },
  { question: 'The 1619 arrival of the White Lion at Point Comfort, Virginia, is significant as the', options: ['first arrival of enslaved Africans anywhere in the Americas', 'founding voyage of England\'s Royal African Company', 'last legal slave voyage to the colony of Virginia', 'first documented Africans in English North America'], correctAnswer: 3, explanation: 'The White Lion brought the first documented enslaved Africans to English North America. Africans had been carried to Spanish and Portuguese America for a century before 1619, the Royal African Company was chartered in 1672, and the trade to Virginia continued long after.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 2, formSet: 2 },
  { question: 'In 1781 the crew of the slave ship Zong threw 132 enslaved Africans overboard. The case became powerful evidence for British abolitionists mainly because', options: ['the owners sued for insurance on the dead as lost cargo', 'the captives took control of the ship and sailed it to safety in Haiti', 'a Spanish warship seized the vessel and freed everyone held aboard', 'the captain was tried and hanged for piracy by a London court'], correctAnswer: 0, explanation: 'The owners sued their insurers for the value of the murdered Africans, so British law treated the killings as a question of lost property, a fact that galvanized abolitionists. There was no shipboard revolt, Spanish rescue, or murder conviction; no one was prosecuted for the killings.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 5, formSet: 1 },
  { question: 'Britain abolished its slave trade in 1807, but the United States did not ban the importation of enslaved Africans until 1808. Why could Congress not act sooner?', options: ['Britain\'s navy controlled American ports until that year', 'The Supreme Court had ruled the trade a protected right', 'The Constitution barred a federal ban before that year', 'A treaty with Spain guaranteed the trade until that year'], correctAnswer: 2, explanation: 'The Constitution prohibited Congress from banning the importation of enslaved people before 1808, and Congress acted as soon as it was permitted. Britain did not control American ports, the Supreme Court issued no such ruling, and no Spanish treaty protected the trade.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 3, formSet: 2 },
  { question: 'Even after Britain (1807) and the United States (1808) banned the Atlantic trade, large numbers of captives still reached the Americas between 1820 and 1860. The best explanation is that', options: ['Britain lifted its ban in the 1820s to supply its sugar colonies', 'Brazil and Cuba kept up imports, and patrols intercepted only some ships', 'Congress repealed the 1808 ban to meet the demand for cotton labor', 'the Royal African Company won a new monopoly on shipments to Cuba'], correctAnswer: 1, explanation: 'Brazil and Cuba continued importing captives until about 1850 and 1867, and British and American patrols intercepted only some of the illegal ships. Britain never lifted its ban, Congress never repealed the 1808 law, and the Royal African Company was long defunct.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 3, formSet: 1 },
  { question: 'Only about 3.6 percent of captives carried across the Atlantic landed in mainland North America, yet about 4 million enslaved people lived in the United States by 1860. Which factor best explains the difference?', options: ['Natural increase, made hereditary by laws tying a child\'s status to the mother', 'Large shipments of captives from Europe that reached the South after 1808', 'Mass enslavement of Native Americans across the Deep South after 1830', 'Legal imports from Africa that continued in large numbers until 1860'], correctAnswer: 0, explanation: 'The enslaved population of North America grew mainly through births, and laws such as Virginia\'s 1662 statute made children of enslaved mothers enslaved for life. Captives did not come from Europe, Native American enslavement could not account for millions, and legal imports from Africa ended in 1808.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 4, formSet: 2 },
  { question: 'The transatlantic slave trade connects most directly to the study of slavery in North America because it', options: ['ended before the first tobacco plantations in Virginia were founded', 'carried mostly European indentured servants to the English colonies', 'supplied the captives whose labor built the plantation system', 'moved captives out of North America to the Caribbean sugar islands'], correctAnswer: 2, explanation: 'The trade fed and shaped the North American plantation system by supplying the enslaved Africans whose labor it depended on. It did not end before Virginia\'s plantations rose, indentured Europeans were a separate labor stream, and the main flow ran from Africa into the Americas.', difficulty: 'easy', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 4, formSet: 1 },
  { question: 'Which development marks the turning point at which the Atlantic slave trade shifted from legal commerce toward smuggling for traders from Britain and the United States?', options: ['The Anglo-American bans of 1807–1808', 'The Spanish asiento grant of 1518', 'The Portuguese auction at Lagos in 1444', 'The White Lion\'s voyage of 1619'], correctAnswer: 0, explanation: 'Once Britain and the United States outlawed the trade in 1807–1808, further voyages by their subjects were illegal and patrols began intercepting ships. The 1444 auction, the 1518 asiento, and the 1619 voyage all expanded the legal trade rather than ending it.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 5, formSet: 2 },
  { question: 'Abolitionists printed thousands of copies of the Brookes diagram (1788), which showed hundreds of Africans packed below the decks of a single slave ship. The diagram\'s main purpose was to', options: ['show ship captains how to load their human cargo more efficiently', 'move the British public by making shipboard crowding visible', 'record the names and origins of captives for their purchasers', 'advertise the Royal African Company\'s voyages to investors'], correctAnswer: 1, explanation: 'Thomas Clarkson and his allies circulated the image to turn public opinion against the trade by showing its cruelty at a glance. It was propaganda for abolition, not a loading guide, a register of names, or an advertisement for slavers.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 6, formSet: 1 },
  { question: 'A historian wants to compare how many captives were carried to Brazil and to British North America across three centuries. Which source would be most useful?', options: ['Olaudah Equiano\'s eyewitness account of his own voyage', 'The Brookes diagram printed by British abolitionists', 'John Newton\'s Thoughts upon the Slave Trade (1788)', 'The Trans-Atlantic Slave Trade Database of voyages'], correctAnswer: 3, explanation: 'The database compiles records of about 36,000 voyages, allowing comparisons of volume by destination over time. Equiano\'s narrative and Newton\'s pamphlet describe individual experiences, and the Brookes diagram depicts a single ship, so none supports large-scale comparison.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 7, formSet: 2 },
  { question: 'Equiano published his account of the Middle Passage in 1789, decades after his capture, for British readers during the abolition debate. When using it as evidence, a historian should', options: ['dismiss it, since enslaved people could not have written such a book', 'weigh how his aim of ending the trade shaped which details he chose', 'treat it as a neutral record that is free of any persuasive purpose', 'assume every detail is exact, since he was an eyewitness to events'], correctAnswer: 1, explanation: 'Sourcing means considering purpose and audience: Equiano wrote to persuade Parliament and the public, which shaped his emphasis without making the account false. Dismissing it ignores the many literate formerly enslaved authors, and treating it as neutral or flawless ignores both purpose and the gap in time.', difficulty: 'hard', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 6, formSet: 1 },
  { question: 'Queen Njinga (c. 1583–1663), ruler of Ndongo and later Matamba in present-day Angola, is remembered chiefly for', options: ['founding the Mali Empire after victory in the Battle of Kirina', 'resisting Portuguese conquest through decades of war and diplomacy', 'leading Jamaica\'s Windward Maroons in their war against Britain', 'writing to Portugal\'s king to protest slave raiding in Kongo'], correctAnswer: 1, explanation: 'Njinga negotiated with the Portuguese governor in Luanda, allied with the Dutch, and waged decades of war to keep her kingdoms independent of Portugal, though she also took part in the trade in captives. Founding Mali was Sundiata\'s achievement, Nanny led the Windward Maroons, and the 1526 letter of protest came from Afonso I of Kongo.', difficulty: 'medium', domain: 'origins-diaspora', topicSlug: 'aas-transatlantic-slave-trade', part: 7, formSet: 2 },

  // ════════════════ Unit 2 — freedom-enslavement ════════════════

  // ── aas-slavery-in-america ──
  { question: 'What distinguished chattel slavery from indentured servitude in colonial Virginia by the early 1700s?', options: ['Servants were bound for life; enslaved people owed a fixed term of years.', 'Servants labored only in fields; enslaved people only in homes.', 'Servants came only from Africa; enslaved people only from Europe.', 'Servants owed a fixed term; enslaved people were property for life.'], correctAnswer: 3, explanation: 'Indentured servants owed labor for a set number of years, while chattel slavery made people inheritable property for life. The reversed version swaps the two systems, both groups did field and household labor, and indentured servants were mostly European.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 1, formSet: 1 },
  { question: 'Anthony Johnson, an Angolan-born man who gained his freedom in Virginia and later held servants of his own, is most useful as evidence that', options: ['Virginia had outlawed slavery before the 1660s', 'free Black colonists were barred from owning land', 'hereditary slavery was already law when he arrived', 'racial lines in early Virginia were not yet fixed'], correctAnswer: 3, explanation: 'Johnson\'s rise from servitude to landholding shows that before the 1660s Virginia\'s labor system had not yet hardened into race-based chattel slavery. Virginia never outlawed slavery, Johnson himself owned land, and hereditary slavery became law only in 1662.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 1, formSet: 2 },
  { question: 'Virginia\'s 1662 law declared that a child "shall be held bond or free only according to the condition of the mother." Its most important effect was to', options: ['make enslavement hereditary through the maternal line', 'free every child whose father was a free Englishman', 'ban marriages between enslaved men and women in Virginia', 'end the importation of new captives into the colony'], correctAnswer: 0, explanation: 'Partus sequitur ventrem tied a child\'s status to the mother, making slavery hereditary and guaranteeing that children of enslaved women, including those fathered by enslavers, were enslaved. It reversed the English rule that followed the father rather than freeing such children, and it neither regulated marriage nor stopped imports.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 1, formSet: 1 },
  { question: 'By 1860 about 4 million enslaved people in the United States produced roughly two-thirds of the world\'s cotton. This fact best supports which argument?', options: ['Slavery was fading as an economic system on the eve of the Civil War.', 'Slavery underwrote national wealth, including northern mills.', 'The cotton gin had reduced planters\' need for enslaved field workers.', 'Northern industry had few economic ties to the plantation South.'], correctAnswer: 1, explanation: 'Cotton grown by enslaved people was the country\'s leading export and fed northern textile mills, shipping, and finance, so slavery financed national, not just southern, wealth. Slavery was expanding rather than fading in 1860, the gin increased demand for enslaved labor, and the North was deeply tied to cotton.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 1, formSet: 2 },
  { question: 'How did Eli Whitney\'s cotton gin (1793) affect slavery in the United States?', options: ['It cut the demand for enslaved labor across the South.', 'It moved planters away from cotton toward tobacco.', 'It made short-staple cotton highly profitable.', 'It ended the domestic trade in enslaved people.'], correctAnswer: 2, explanation: 'The gin made short-staple cotton profitable to grow, so slavery spread into the Deep South and output soared by 1860. Because the machine sped processing rather than picking, it increased demand for enslaved labor, and the domestic slave trade grew as a result.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 2, formSet: 1 },
  { question: 'The Virginia Slave Codes of 1705 are significant because they', options: ['first made slavery legal in any English colony', 'abolished indentured servitude across the colony', 'built a full race-based legal regime others copied', 'let enslaved people testify against white colonists'], correctAnswer: 2, explanation: 'The 1705 codes gathered earlier laws into a comprehensive race-based system of control that became a model for other colonies. Massachusetts legalized slavery first, in 1641, indentured servitude continued, and the codes stripped rather than granted legal rights.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 2, formSet: 2 },
  { question: 'In 1641, which became the first English colony in North America to legalize slavery in its written law?', options: ['Virginia', 'Massachusetts', 'South Carolina', 'Maryland'], correctAnswer: 1, explanation: 'Massachusetts recognized slavery in its 1641 Body of Liberties, before any other English colony did so by statute. Virginia\'s key slavery laws came in 1662 and 1705, and South Carolina was not founded until 1670.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 2, formSet: 1 },
  { question: 'Which sequence places these developments in the correct chronological order?', options: ['Cotton gin, partus law, import ban, Virginia Slave Codes', 'Partus law, Virginia Slave Codes, cotton gin, import ban', 'Virginia Slave Codes, partus law, import ban, cotton gin', 'Import ban, partus law, Virginia Slave Codes, cotton gin'], correctAnswer: 1, explanation: 'Virginia\'s partus law came in 1662, the Slave Codes in 1705, the cotton gin in 1793, and the federal import ban in 1808. Each other sequence misplaces either the Slave Codes or the cotton gin.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 3, formSet: 2 },
  { question: 'Which statement accurately compares Massachusetts\'s 1641 law with Virginia\'s 1662 law?', options: ['Massachusetts made slavery hereditary; Virginia first made slavery legal in English America.', 'Massachusetts abolished slavery; Virginia created the colony\'s first indentured servitude.', 'Massachusetts legalized slavery; Virginia made enslavement pass from mother to child.', 'Massachusetts banned slave imports; Virginia allowed enslaved people to buy freedom.'], correctAnswer: 2, explanation: 'Massachusetts was the first English colony to legalize slavery, and Virginia\'s 1662 law made slavery hereditary through the mother. The swapped version reverses the two laws, and neither colony abolished slavery, banned imports, or created a right to self-purchase in these acts.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 3, formSet: 1 },
  { question: 'Colonial codes barred enslaved people from traveling without passes, gathering in groups, or owning drums. Historians often read such codes as evidence of resistance as well as control because', options: ['the rules reveal what enslaved people were actually doing', 'enslaved people helped write the codes in colonial legislatures', 'the codes granted enslaved people a legal right to self-defense', 'colonial courts almost never enforced any part of the codes'], correctAnswer: 0, explanation: 'Laws against travel, gatherings, and drums respond to what enslaved people were doing: moving, meeting, and organizing, as at Stono in 1739. Enslaved people had no role in writing the codes, the codes stripped rather than granted rights, and they were enforced harshly.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 4, formSet: 2 },
  { question: 'Harriet Jacobs\'s Incidents in the Life of a Slave Girl (1861) adds to the history of resistance mainly by showing', options: ['how armed revolts were planned in the Carolina Lowcountry', 'how enslaved women fought sexual exploitation by enslavers', 'how the cotton gin changed the pace of fieldwork in Georgia', 'how the Missouri Compromise was negotiated in Washington'], correctAnswer: 1, explanation: 'Jacobs described her own refusal of her enslaver\'s sexual pursuit and her years in hiding, bringing gendered violence and women\'s resistance into view. Earlier male-authored narratives largely omitted this, and her book is not about revolts, the cotton gin, or congressional bargaining.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 4, formSet: 1 },
  { question: 'After Congress banned the importation of enslaved Africans in 1808, the expanding cotton states obtained most of their enslaved workers through', options: ['illegal shipments from Brazil', 'hiring free Black wage laborers', 'forced sales from the Upper South', 'the enslavement of Native Americans'], correctAnswer: 2, explanation: 'The domestic slave trade forcibly moved about a million people from the Upper South to the cotton states, splitting families. Some illegal imports occurred, but they were small by comparison, and neither wage labor nor Native American enslavement supplied the cotton boom.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 5, formSet: 2 },
  { question: 'Which statement describes a CONTINUITY in American slavery from the 1705 Virginia Slave Codes to 1860?', options: ['The Atlantic trade remained the main source of new enslaved workers.', 'Slavery stayed confined to the tobacco colonies of the Chesapeake.', 'Most enslaved people continued to live in Virginia and Maryland.', 'The law treated enslaved people as inheritable property by race.'], correctAnswer: 3, explanation: 'From 1705 to 1860 the law defined enslaved people as race-based, hereditary property. The Atlantic trade was replaced by the domestic trade after 1808, and slavery spread west and south into the cotton Deep South, so the Chesapeake was no longer its center.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 5, formSet: 2 },
  { question: 'Read the excerpt, adapted from Frederick Douglass\'s Narrative (1845), describing the moment his enslaver forbade his wife to keep teaching young Douglass to read: "From that moment, I understood the pathway from slavery to freedom." Douglass\'s point is that', options: ['a kind enslaver could make bondage bearable', 'faith alone would bring the enslaved their freedom', 'learning to read could open a way out of bondage', 'escape depended mainly on help from white allies'], correctAnswer: 2, explanation: 'Hearing his enslaver warn that learning would make him unfit for slavery, Douglass concluded that literacy was the path to freedom, which is why it was forbidden. The passage condemns rather than excuses enslavers, and it credits learning, not faith or outside help, as the key.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 6, formSet: 1 },
  { question: 'Harriet Jacobs published Incidents (1861) under the pen name Linda Brent and addressed it chiefly to northern white women. The best explanation for this choice of audience is that she', options: ['wanted southern planters to buy the book and reform their own estates', 'sought sympathy through readers\' ideals of family and virtue', 'intended to prove to northern bankers that cotton remained profitable', 'meant to answer Douglass\'s Narrative point by point for male readers'], correctAnswer: 1, explanation: 'Jacobs wrote to move northern women who shared ideals of motherhood and purity, showing how slavery violated both and urging them to act. The book was aimed at northerners rather than planters, was not an economic tract, and complemented rather than rebutted Douglass.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 6, formSet: 2 },
  { question: 'Solomon Northup, a free Black man from New York, was kidnapped in 1841 and held as a slave in Louisiana for twelve years. His story best illustrates that', options: ['legal freedom outside the South gave little safety', 'New York still practiced slavery in the 1840s', 'Louisiana had banned the domestic slave trade', 'kidnapping was punished harshly in the South'], correctAnswer: 0, explanation: 'Northup\'s kidnapping shows how the demand of the domestic trade made even legally free Black Americans vulnerable. New York had ended slavery by 1827, Louisiana was a major market for the domestic trade, and his kidnappers sold him with impunity.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 7, formSet: 1 },
  { question: 'A student is writing about how formerly enslaved people\'s own accounts exposed slavery\'s cruelty to readers in the free states before the Civil War. Which pair of sources fits that purpose best?', options: ['The 1662 partus law and the 1705 Virginia Slave Codes', 'The cotton gin patent and the Missouri Compromise', 'The Massachusetts Body of Liberties and the 1808 ban', 'Douglass\'s Narrative and Northup\'s Twelve Years a Slave'], correctAnswer: 3, explanation: 'Douglass (1845) and Northup (1853) wrote first-person accounts of bondage that reached large northern audiences. The other pairs are laws, a patent, and a political settlement, which show how slavery was structured but are not testimony from the enslaved.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-slavery-in-america', part: 7, formSet: 2 },

  // ── aas-resistance-abolition ──
  { question: 'A plantation overseer\'s journal complains that enslaved workers keep "losing" hoes, slow down during the harvest, and claim to be too sick to work. Historians would classify these actions as', options: ['armed revolt', 'moral suasion', 'everyday resistance', 'manumission'], correctAnswer: 2, explanation: 'Tool-breaking, work slowdowns, and feigned illness are forms of everyday resistance that enslaved people used to contest their exploitation without open rebellion. Armed revolt involves organized violence, moral suasion is the abolitionist strategy of persuasion, and manumission is a legal grant of freedom.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 1, formSet: 1 },
  { question: 'Abolitionists who followed William Lloyd Garrison differed from those who backed the Liberty and Free Soil parties mainly in that the Garrisonians', options: ['relied on moral persuasion and refused to take part in electoral politics', 'favored a slow, compensated emancipation over immediate abolition', 'promoted the resettlement of freed people in the colony of Liberia', 'ran their own antislavery candidates for seats in the U.S. Congress'], correctAnswer: 0, explanation: 'Garrisonians practiced moral suasion, demanding immediate abolition while rejecting voting and party politics, whereas Liberty and Free Soil supporters pursued change through elections. Garrison opposed gradualism and colonization, and running candidates was the political-action approach he rejected.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 1, formSet: 2 },
  { question: 'Frederick Douglass, publisher of The North Star (1847), broke with William Lloyd Garrison in the early 1850s chiefly over whether', options: ['women should be permitted to speak at antislavery meetings', 'the Constitution could serve as an antislavery tool in politics', 'formerly enslaved people should publish their own newspapers', 'free Black Americans ought to emigrate to Liberia or Haiti'], correctAnswer: 1, explanation: 'Garrison condemned the Constitution as proslavery and shunned voting, while Douglass came to read it as an antislavery document that could be used through politics. Both men supported women speaking, the newspaper was a source of friction but not the core disagreement, and neither endorsed emigration.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 1, formSet: 1 },
  { question: 'Why did news of the Haitian Revolution (1791–1804) alarm enslavers across the United States?', options: ['It showed that enslaved people could overthrow slavery and found a nation.', 'Haitian armies threatened to invade Louisiana to free its enslaved people.', 'France responded by freeing all the people enslaved in its former colonies.', 'Haitian ports stopped shipping the sugar that southern planters depended on.'], correctAnswer: 0, explanation: 'The revolution, led by Toussaint L\'Ouverture and others, was the only slave revolt to create a nation, founding Haiti in 1804, and it fed enslavers\' fears of rebellion at home. Haiti never threatened to invade Louisiana, France restored slavery elsewhere in 1802, and southern planters did not depend on Haitian sugar.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 1, formSet: 2 },
  { question: 'In the aftermath of Nat Turner\'s 1831 rebellion in Southampton County, Virginia, southern legislatures most commonly responded by', options: ['adopting gradual emancipation laws after long public debate', 'funding new public schools for the children of free Black families', 'passing harsher codes that restricted Black literacy and preaching', 'closing the domestic trade to buyers from the cotton states'], correctAnswer: 2, explanation: 'After the rebellion, southern states tightened slave codes, outlawing teaching enslaved people to read and restricting Black preachers and gatherings, and Congress later adopted gag rules against antislavery petitions. Virginia debated gradual emancipation in 1831–1832 but rejected it, and no state closed the domestic trade or funded Black schools.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 2, formSet: 1 },
  { question: 'South Carolina\'s Negro Act of 1740, which restricted the movement, assembly, and education of enslaved people, was a direct response to', options: ['the Stono Rebellion of 1739', 'Nat Turner\'s revolt of 1831', 'Denmark Vesey\'s plot of 1822', 'the Haitian Revolution of 1791'], correctAnswer: 0, explanation: 'The Stono Rebellion, in which enslaved Africans killed about twenty white colonists, prompted South Carolina to pass the Negro Act in 1740. The other events all occurred decades after the law was enacted.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 2, formSet: 2 },
  { question: 'How did the Fugitive Slave Act of 1850 affect public opinion in the North?', options: ['It ended the Underground Railroad by making all escape routes too costly.', 'It assured most northerners that slavery would soon die out by itself.', 'It made northerners help capture freedom seekers, pushing many toward antislavery.', 'It guaranteed accused fugitives a jury trial and so calmed northern fears.'], correctAnswer: 2, explanation: 'By requiring northern officials and citizens to assist in returning fugitives, and by denying accused people a jury trial, the law brought slavery\'s reach into free states and radicalized northern opinion. The Underground Railroad continued, and the law heightened rather than calmed sectional fears.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 3, formSet: 1 },
  { question: 'Which statement best explains why the Haitian Revolution had a far larger outcome than the Stono Rebellion?', options: ['Haitian rebels defeated European armies and founded a state; Stono was put down within days.', 'Haitian rebels won freedom by a treaty with Britain; Stono ended with the colony\'s abolition.', 'Haitian rebels won a vote in the French assembly; Stono led to the founding of new maroon towns.', 'Haitian rebels were all free people of color; Stono was planned by white abolitionists in London.'], correctAnswer: 0, explanation: 'In Saint-Domingue the revolutionaries defeated French, Spanish, and British forces and founded independent Haiti in 1804, while the Stono uprising in South Carolina was crushed quickly and led to the restrictive Negro Act. Neither revolt ended in a treaty-based freedom, a vote, or colonial abolition, and Stono was led by enslaved Africans.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 3, formSet: 2 },
  { question: 'Denmark Vesey, who organized a planned 1822 uprising in Charleston, was a founder of the city\'s African Methodist Episcopal congregation. That connection best illustrates how', options: ['the AME Church officially opposed abolition in the South', 'Black churches could serve as bases for plotting resistance', 'white abolitionists from Boston planned and directed the plot', 'Charleston\'s free Black community had no ties to the enslaved'], correctAnswer: 1, explanation: 'Independent Black churches gave free and enslaved people a place to meet and organize, which is why Charleston authorities destroyed Vesey\'s church after the plot was exposed. The AME tradition was antislavery, the plot was planned locally by Black Charlestonians, and Vesey\'s network linked free and enslaved people.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 4, formSet: 1 },
  { question: 'Richard Allen\'s founding of the African Methodist Episcopal Church in Philadelphia in 1816 belongs in the history of resistance mainly because it', options: ['led enslaved people in an armed revolt across the Upper South', 'was organized by Garrison to spread moral suasion in the North', 'urged free Black Philadelphians to resettle in West Africa', 'created an independent Black institution beyond white control'], correctAnswer: 3, explanation: 'Allen built the first independent Black denomination after white Methodists segregated Black worshippers, giving free Black communities an institutional base for mutual aid and antislavery work. The church was not a military movement, Allen founded it before Garrison\'s rise, and Allen opposed colonization.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 4, formSet: 2 },
  { question: 'The Emancipation Proclamation (1863) marked a decisive shift in the Civil War mainly because it', options: ['ended slavery at once in every state and territory of the Union', 'made ending slavery a Union war aim and opened the army to Black men', 'freed the enslaved people held in loyal border states like Kentucky', 'granted citizenship and voting rights to all freed people in the South'], correctAnswer: 1, explanation: 'The Proclamation declared free those enslaved in Confederate-held areas, turned the war into a fight against slavery, and authorized Black enlistment. It did not apply to loyal border states or abolish slavery nationwide, which awaited the Thirteenth Amendment, and citizenship came with the Fourteenth.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 5, formSet: 1 },
  { question: 'John Brown\'s 1859 raid on the federal arsenal at Harpers Ferry failed, yet it deepened the sectional crisis because', options: ['it freed thousands of enslaved Virginians who then fled to Canada', 'Abraham Lincoln and the Republican Party openly endorsed the attack', 'Congress responded to it by repealing the Fugitive Slave Act of 1850', 'abolitionists hailed him as a martyr, alarming white southerners'], correctAnswer: 3, explanation: 'After Brown was hanged, many northern abolitionists praised him as a martyr, convincing white southerners that the North supported violent attacks on slavery. The raid freed almost no one, Lincoln and the Republicans condemned it, and the Fugitive Slave Act stayed in force.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 5, formSet: 2 },
  { question: 'Read the excerpt from Frederick Douglass\'s speech "What to the Slave Is the Fourth of July?" (1852): "What, to the American slave, is your 4th of July? I answer: a day that reveals to him, more than all other days in the year, the gross injustice and cruelty to which he is the constant victim." Douglass\'s central argument is that', options: ['enslaved people should join in the national celebration as citizens', 'independence from Britain had already set the nation on a path to freedom', 'enslaved Americans ought to emigrate to Haiti rather than wait for change', 'praising liberty in a land of bondage exposed national hypocrisy'], correctAnswer: 3, explanation: 'Douglass used the holiday to indict a nation that praised liberty while millions remained enslaved. He did not urge the enslaved to celebrate, he denied that independence had brought freedom to Black Americans, and the speech makes no case for emigration.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 6, formSet: 1 },
  { question: 'The Confessions of Nat Turner (1831) was recorded and published by Thomas Gray, a white lawyer, from interviews with Turner in jail before his execution. A historian should treat its account of Turner\'s motives with care chiefly because', options: ['Turner wrote the book himself years later, after reaching freedom', 'Gray\'s own aims and editing shaped how Turner\'s words reached readers', 'the text was a novel loosely based on rumors about the rebellion', 'the Virginia courts ordered every copy destroyed before it was read'], correctAnswer: 1, explanation: 'Because Turner\'s words come to us through Gray, who chose what to record and published the pamphlet for profit and a white audience, the source is mediated and must be read critically. Turner was executed in 1831 and did not write it, it is not a novel, and copies circulated widely.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 6, formSet: 2 },
  { question: 'Copies of David Walker\'s Appeal (1829), written by a free Black Bostonian, were sewn into sailors\' clothing to reach southern ports. This method of distribution shows that', options: ['the pamphlet could be sold openly in southern bookshops', 'Walker wrote mainly for readers in Britain and the Caribbean', 'covert networks carried radical ideas into the slave South', 'southern legislatures welcomed debate over its arguments'], correctAnswer: 2, explanation: 'Walker relied on Black sailors and other networks to smuggle his call for resistance into the South, where authorities banned it and offered rewards for his capture. Its secrecy shows it could not be sold openly, it was addressed to Black Americans, and southern lawmakers responded with censorship.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 6, formSet: 1 },
  { question: 'Which figure guided the 1863 Combahee River Raid in South Carolina, which freed about 750 enslaved people?', options: ['Sojourner Truth', 'Harriet Jacobs', 'Harriet Tubman', 'Maria Stewart'], correctAnswer: 2, explanation: 'Harriet Tubman, already known for about thirteen Underground Railroad missions, guided Union troops in the Combahee River Raid. Sojourner Truth and Maria Stewart were orators, and Harriet Jacobs wrote Incidents in the Life of a Slave Girl.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 7, formSet: 2 },
  { question: 'Which leader is most closely associated with the revolution that created the first Black-led independent state in the Americas?', options: ['Gabriel', 'Nat Turner', 'Denmark Vesey', 'Toussaint L\'Ouverture'], correctAnswer: 3, explanation: 'Toussaint L\'Ouverture led the Haitian Revolution, which produced independent Haiti in 1804. Gabriel (1800), Denmark Vesey (1822), and Nat Turner (1831) led or planned revolts in the United States that were crushed.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-resistance-abolition', part: 7, formSet: 1 },

  // ── aas-freedom-enslavement ──
  { question: 'Pennsylvania\'s Gradual Abolition Act of 1780 freed which people?', options: ['Every enslaved person in the state on the day the law took effect', 'Only those whose owners filed papers agreeing to free them', 'Only enslaved men who had served in the Continental Army', 'Children born after the law, once they had served for years'], correctAnswer: 3, explanation: 'Like the later New York (1799) and New Jersey (1804) laws, Pennsylvania\'s act freed people by birthdate: children born after it passed became free only after serving into adulthood, while those already enslaved stayed enslaved. It was not immediate, limited to soldiers, or dependent on owner consent.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 1, formSet: 1 },
  { question: 'After the American Revolution, some enslavers in the Upper South freed individual enslaved people by deed or by will. This practice is called', options: ['gradual emancipation', 'colonization', 'manumission', 'abolition'], correctAnswer: 2, explanation: 'Manumission is an owner\'s private grant of freedom, a practice many southern states restricted after the 1820s. Gradual emancipation and abolition are actions taken by law for whole populations, and colonization refers to resettling free Black people outside the country.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 1, formSet: 2 },
  { question: 'In Dred Scott v. Sandford (1857), Chief Justice Roger Taney wrote that Black people had "no rights which the white man was bound to respect." The decision held that', options: ['those of African descent could never be citizens of the United States', 'Congress had full power to bar slavery from all the western territories', 'free Black men in the North were entitled to vote in federal elections', 'an enslaved person brought onto free soil became free automatically'], correctAnswer: 0, explanation: 'Taney\'s ruling declared that people of African descent, free or enslaved, could not be U.S. citizens, and it also held that Congress could not ban slavery in the territories. The decision denied rather than affirmed voting rights, and it rejected Scott\'s claim that residence on free soil had freed him.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 1, formSet: 1 },
  { question: 'Prince Hall founded an African lodge of Freemasons in Boston (chartered 1784) and petitioned the Massachusetts legislature to end slavery. His activities best illustrate how free Black northerners', options: ['avoided public life to protect their legal status', 'relied on white patrons to speak on their behalf', 'built institutions and pressed lawmakers for rights', 'focused mainly on emigrating to West Africa'], correctAnswer: 2, explanation: 'Hall combined institution-building with direct appeals to lawmakers, a pattern of free Black civic activism in the early republic. He acted publicly and in his own name, and his petitions sought rights at home rather than emigration.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 1, formSet: 2 },
  { question: 'The first National Negro Convention, held in Philadelphia in 1830, is significant because', options: ['it created the African Methodist Episcopal Church as a denomination', 'Black leaders from several states organized a joint response', 'it founded the colony of Liberia for free Black Americans to settle', 'it secured the immediate end of slavery in the state of Pennsylvania'], correctAnswer: 1, explanation: 'The 1830 convention began a movement in which Black delegates from many states met to coordinate action on rights, education, and opposition to colonization. The AME Church dates from 1816, Liberia was the work of the American Colonization Society, and Pennsylvania\'s emancipation was gradual, beginning in 1780.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 2, formSet: 1 },
  { question: 'Philadelphia\'s Free African Society, founded in 1787 by Richard Allen and Absalom Jones, was primarily a', options: ['mutual-aid group supporting free Black families', 'colonization society sending settlers to Liberia', 'militia company formed to resist slave catchers', 'weekly newspaper aimed at Black readers'], correctAnswer: 0, explanation: 'The Free African Society pooled dues to aid the sick, widows, and orphans and laid groundwork for independent Black churches. It was not a colonization body, a militia, or a newspaper; the first Black newspaper, Freedom\'s Journal, appeared in 1827.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 2, formSet: 2 },
  { question: 'How did free Black Americans respond to the American Colonization Society, founded in 1816 to resettle free Black people in Africa?', options: ['They united behind resettlement and moved to Liberia in large numbers.', 'They ignored it, since the society worked only in the Deep South.', 'They united instead behind a plan to resettle together in Haiti.', 'They split, and many leaders rejected leaving the country.'], correctAnswer: 3, explanation: 'Black opinion was sharply divided: some emigrated, but leaders such as James Forten led mass meetings rejecting removal from the country they had helped build. Only a small minority went to Liberia, the society was active nationally, and Haitian emigration drew interest but never united Black opinion.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 3, formSet: 1 },
  { question: 'Which statement accurately contrasts the Free African Society (1787) with the American Colonization Society (1816)?', options: ['The first resettled free Black families in Haiti; the second built Black churches in Philadelphia.', 'The first was a Black mutual-aid group; the second was a white-led plan to resettle free Black people in Liberia.', 'The first was a state agency for gradual emancipation; the second ran the federal fugitive slave courts.', 'The first was a white abolitionist society; the second was a Black convention that met in Philadelphia.'], correctAnswer: 1, explanation: 'Black Philadelphians founded the Free African Society to support one another, while white reformers and some enslavers founded the American Colonization Society to remove free Black people to Africa. The other contrasts misidentify who founded each group and what it did.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 3, formSet: 2 },
  { question: 'James Forten, a wealthy Black sailmaker in Philadelphia, helped finance William Lloyd Garrison\'s newspaper The Liberator and the Black convention movement. His role best supports the claim that', options: ['abolitionism depended chiefly on money from southern planters', 'most free Black Americans stayed out of antislavery work', 'free Black communities gave money and leaders to abolitionism', 'The Liberator was funded mainly by the federal government'], correctAnswer: 2, explanation: 'Forten\'s backing shows that free Black communities were the institutional and financial backbone of abolitionism; Black subscribers kept The Liberator afloat in its early years. Southern planters opposed abolition, Black Americans were central to it, and the paper received no federal money.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 4, formSet: 1 },
  { question: 'Why do historians connect the growth of free Black institutions after 1787 to the rise of the abolition movement?', options: ['Free Black institutions avoided politics to protect their charters.', 'White abolitionists founded and ran most of these institutions.', 'These institutions focused only on emigration to West Africa.', 'Black churches and societies sheltered antislavery organizing.'], correctAnswer: 3, explanation: 'Churches, mutual-aid societies, and conventions gave antislavery activists meeting places, networks, and leaders. Black Americans founded and led these institutions, which were deeply political, and most opposed emigration rather than promoting it.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 4, formSet: 2 },
  { question: 'Under the Fugitive Slave Act of 1850, a federal commissioner was paid a larger fee for ordering an accused person returned to slavery than for setting the person free. Critics charged that this provision', options: ['guaranteed each accused person a full trial before a jury', 'rewarded officials for ruling against the accused', 'shielded free Black northerners from kidnapping and sale', 'left all fugitive cases to the courts of the free states'], correctAnswer: 1, explanation: 'Paying more for a return than a release rewarded commissioners for sending people south, and the law also denied the accused a jury trial or the right to testify. It exposed free Black northerners to seizure rather than protecting them, and it moved cases to federal commissioners, away from state courts.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 5, formSet: 1 },
  { question: 'Taken together, Pennsylvania\'s Gradual Abolition Act (1780) and the Dred Scott decision (1857) show that between 1780 and 1857', options: ['state laws narrowed slavery in places while federal law curtailed Black citizenship claims', 'federal law steadily expanded Black citizenship while the states resisted every reform', 'both the states and the federal courts moved steadily toward full equal citizenship', 'neither state nor federal law did much to change the status of free Black Americans'], correctAnswer: 0, explanation: 'Northern states such as Pennsylvania ended slavery gradually, but by 1857 the Supreme Court denied that any person of African descent could be a citizen, showing freedom expanding locally while federal law narrowed Black rights. The other choices misstate the direction of state or federal change.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 5, formSet: 2 },
  { question: 'Read the excerpt from David Walker\'s Appeal (1829): "America is more our country, than it is the whites—we have enriched it with our blood and tears." In context, Walker is arguing', options: ['that Black Americans should resettle in Liberia, where they would be free', 'that white Americans alone had built the nation and so deserved to rule it', 'against colonization, claiming America as the nation Black labor built', 'that enslaved people should wait patiently for slaveholders to free them'], correctAnswer: 2, explanation: 'Walker answered the colonization movement by asserting that Black Americans\' labor and suffering made the United States their country. He rejected removal to Liberia, he denied that white Americans alone built the nation, and his Appeal called for resistance rather than patience.', difficulty: 'hard', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 6, formSet: 1 },
  { question: 'Read the excerpt, adapted from Maria W. Stewart\'s writings of the early 1830s: "How long shall the daughters of Africa be compelled to bury their minds and talents beneath a load of iron pots and kettles?" Stewart\'s main point is that', options: ['Black women\'s gifts were being wasted in a life of menial labor', 'Black women should leave public life and focus on their homes', 'Black women in Boston already enjoyed equal access to education', 'Black women ought to return to Africa to find meaningful work'], correctAnswer: 0, explanation: 'Stewart protested that racism and sexism confined Black women to domestic drudgery and urged them to cultivate their minds and claim public roles. She did not counsel retreat into the home, she denied that equal opportunity existed, and her question about Africa\'s daughters is about heritage, not emigration.', difficulty: 'medium', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 6, formSet: 2 },
  { question: 'The AME Church\'s Discipline (1817), the founding rulebook of the new denomination, would be most useful to a historian studying', options: ['how planters organized cotton production', 'how Black Americans governed their own faith', 'how Congress debated the Missouri Compromise', 'how Britain enforced its slave-trade ban'], correctAnswer: 1, explanation: 'The Discipline was the charter of an independent Black denomination, so it shows how Black Americans governed their own religious institution. It contains nothing about plantation production, congressional debates, or British naval enforcement.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 6, formSet: 1 },
  { question: 'Which figure founded the African Methodist Episcopal Church in 1816 and became its first bishop?', options: ['Absalom Jones', 'Prince Hall', 'James Forten', 'Richard Allen'], correctAnswer: 3, explanation: 'Richard Allen founded the AME Church and was consecrated its first bishop. Absalom Jones, his partner in the Free African Society, became the first Black Episcopal priest, Prince Hall founded a Black Masonic lodge in Boston, and James Forten was a sailmaker and financier of abolition.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 7, formSet: 2 },
  { question: 'Which woman lectured publicly on political topics in Boston in 1832–1833, among the first American-born women to do so?', options: ['Phillis Wheatley', 'Maria W. Stewart', 'Harriet Jacobs', 'Harriet Tubman'], correctAnswer: 1, explanation: 'Maria W. Stewart delivered political lectures in Boston in 1832–1833, calling on Black women and men to claim their rights. Wheatley was a poet who died in 1784, Jacobs wrote her narrative in 1861, and Tubman was known for Underground Railroad missions.', difficulty: 'easy', domain: 'freedom-enslavement', topicSlug: 'aas-freedom-enslavement', part: 7, formSet: 1 },

  // ════════════════ Unit 3 — practice-freedom ════════════════

  // ── aas-reconstruction-jim-crow ──
  { question: 'Which constitutional amendment, ratified in 1870, barred states from denying men the vote on account of race?', options: ['The Thirteenth', 'The Fourteenth', 'The Nineteenth', 'The Fifteenth'], correctAnswer: 3, explanation: 'The Fifteenth Amendment (1870) prohibited race-based denial of the vote to men. The Thirteenth (1865) abolished slavery, the Fourteenth (1868) defined citizenship and equal protection, and the Nineteenth (1920) addressed women\'s suffrage.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 1, formSet: 1 },
  { question: 'Which statement best describes the work of the Freedmen\'s Bureau between 1865 and 1872?', options: ['It granted every freed family permanent title to confiscated land.', 'It enforced the Black Codes on behalf of former slaveholders.', 'It recruited Black regiments to fight for the Union army.', 'It ran schools and oversaw labor contracts for freedpeople.'], correctAnswer: 3, explanation: 'The Bureau founded schools, supervised labor contracts, and offered legal aid to freedpeople. Most land it briefly held was returned to former owners, it worked against rather than for the Black Codes, and Black regiments were raised during the war by the army itself.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 1, formSet: 2 },
  { question: 'A southern state constitution of the 1890s exempted men from its literacy test if their ancestors had been eligible to vote before 1867. This provision is known as a', options: ['grandfather clause', 'white primary', 'poll tax', 'Black Code'], correctAnswer: 0, explanation: 'Grandfather clauses let white men whose ancestors voted before Black men could vote skip literacy tests, so the tests fell mainly on Black citizens. A poll tax charged a fee to vote, a white primary excluded Black voters from party nominations, and Black Codes were 1865–1866 labor laws.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 1, formSet: 1 },
  { question: 'In 1870 Hiram Revels of Mississippi became the first Black U.S. senator, filling the seat Jefferson Davis had once held. His election is most significant as evidence that', options: ['Reconstruction briefly opened national office to Black men in the former Confederacy', 'the Fifteenth Amendment had permanently secured Black officeholding across the South', 'Mississippi had abolished slavery on its own before the outbreak of the Civil War', 'senators in the 1870s were chosen by a direct popular vote of each state\'s citizens'], correctAnswer: 0, explanation: 'Revels\'s seating in Davis\'s former seat dramatized how far Reconstruction had opened political life to Black men, though those gains were later reversed. The Fifteenth Amendment did not secure lasting officeholding, Mississippi did not abolish slavery on its own, and state legislatures chose senators until the Seventeenth Amendment.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 1, formSet: 2 },
  { question: 'The Compromise of 1877 brought Reconstruction to an end by', options: ['ratifying the Fifteenth Amendment in exchange for southern votes', 'restoring the 40-acre land grants that Andrew Johnson had revoked', 'creating the Freedmen\'s Bureau to oversee the former Confederacy', 'withdrawing federal troops from the South after Hayes took office'], correctAnswer: 3, explanation: 'In the disputed 1876 election, Democrats accepted Rutherford B. Hayes as president and he withdrew the remaining federal troops, ending federal protection for Black political rights in the South. The Fifteenth Amendment dated from 1870, the Bureau from 1865, and the land grants were never restored.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 2, formSet: 1 },
  { question: 'General Sherman\'s Special Field Order No. 15 (1865) set aside coastal land for freedpeople in plots of up to 40 acres, but President Andrew Johnson soon reversed it. The reversal mattered because', options: ['freedpeople gained clear title to the land and became independent farmers', 'most freedpeople were left landless, and many turned to sharecropping', 'the land was instead granted to Union veterans who settled the coast', 'Congress responded by paying cash reparations to formerly enslaved people'], correctAnswer: 1, explanation: 'Johnson returned the land to former Confederate owners, so most freedpeople had no land of their own and many entered sharecropping arrangements that bound them to debt. The reversal took the land away rather than securing it, it did not go to veterans, and Congress never paid reparations.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 2, formSet: 2 },
  { question: 'In Plessy v. Ferguson (1896), the Supreme Court', options: ['struck down segregated seating on interstate railroads', 'upheld laws requiring "separate but equal" facilities', 'ruled that Black Americans could never become citizens', 'held that grandfather clauses violated the Constitution'], correctAnswer: 1, explanation: 'Plessy upheld Louisiana\'s law segregating railroad cars under the doctrine of "separate but equal," with only Justice Harlan dissenting. Denying citizenship was the 1857 Dred Scott ruling, and the Court did not strike down segregation or grandfather clauses in this case.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 3, formSet: 1 },
  { question: 'The 1898 Wilmington insurrection in North Carolina is significant because', options: ['a Black militia took control of the city\'s government by force', 'federal troops restored the city\'s elected officials to power', 'a white mob violently overthrew an elected multiracial government', 'the state ended its convict-lease system in response to the violence'], correctAnswer: 2, explanation: 'Armed white supremacists drove Wilmington\'s elected multiracial government from office, killed Black residents, and forced many to flee, a coup the federal government did nothing to reverse. Black residents were the targets rather than the attackers, and the violence did not end convict leasing.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 3, formSet: 2 },
  { question: 'Which statement accurately compares the Fourteenth Amendment (1868) and the Fifteenth Amendment (1870)?', options: ['The Fourteenth abolished slavery; the Fifteenth defined who was a citizen.', 'The Fourteenth granted women the vote; the Fifteenth ended poll taxes.', 'The Fourteenth defined citizenship; the Fifteenth barred race-based denial of the vote.', 'The Fourteenth created the Freedmen\'s Bureau; the Fifteenth ended Reconstruction.'], correctAnswer: 2, explanation: 'The Fourteenth established birthright citizenship and equal protection, and the Fifteenth barred denying men the vote because of race. Slavery was abolished by the Thirteenth, women\'s suffrage came in 1920, poll taxes in federal elections ended in 1964, and the Bureau was created by statute in 1865.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 3, formSet: 1 },
  { question: 'Which development most directly links the post-Reconstruction South to the Great Migration of the 1910s?', options: ['The Freedmen\'s Bureau expanded its schools across the rural South.', 'Lynching and disfranchisement pushed Black southerners to leave.', 'Congress gave Black families homesteads on northern farmland.', 'Federal courts began enforcing the Fifteenth Amendment strictly.'], correctAnswer: 1, explanation: 'Jim Crow violence, disfranchisement, and economic exploitation were the push factors behind the Great Migration. The Freedmen\'s Bureau closed in 1872, Congress offered no northern homesteads to Black families, and federal courts did not enforce Black voting rights in this period.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 4, formSet: 2 },
  { question: 'After a white mob lynched three Black grocers in Memphis in 1892, Ida B. Wells urged Black residents to leave the city, and thousands did. Her call anticipates which later development?', options: ['The Atlanta Compromise accepting segregation', 'The withdrawal of federal troops in 1877', 'The Great Migration to northern cities', 'The founding of the Freedmen\'s Bureau'], correctAnswer: 2, explanation: 'Wells\'s call to leave a violent South foreshadowed the Great Migration, in which millions fled Jim Crow for the North and West. The Atlanta Compromise urged Black southerners to stay and accommodate, and the troop withdrawal and Freedmen\'s Bureau came before 1892.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 4, formSet: 1 },
  { question: 'Mississippi\'s 1890 constitution, the model for the "Mississippi Plan," cut Black voting sharply without violating the Fifteenth Amendment\'s text. How?', options: ['It barred Black men from voting by naming their race outright.', 'It used poll taxes and literacy tests that omitted race.', 'It held a state vote to repeal the Fifteenth Amendment locally.', 'It required federal approval before any Black man could vote.'], correctAnswer: 1, explanation: 'Poll taxes and literacy tests were race-neutral on paper but administered to exclude Black voters, which let Mississippi evade the Fifteenth Amendment; other southern states copied the plan. An explicit racial bar would have violated the amendment, states cannot repeal federal amendments, and no federal approval was required.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 5, formSet: 2 },
  { question: 'Which statement best describes change in Black political participation in the South between 1870 and 1900?', options: ['It grew steadily as federal troops protected Black voters.', 'It changed little because few Black men had ever voted.', 'Gains made under the Fifteenth Amendment were reversed.', 'It rose sharply after 1877 as Democrats courted Black votes.'], correctAnswer: 2, explanation: 'Black men voted and held office in large numbers during Reconstruction, but after 1877 violence, fraud, and laws such as the Mississippi Plan stripped most of them of the vote by 1900. Federal protection ended in 1877, Black participation had been substantial, and Democratic "redeemers" suppressed rather than courted Black votes.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 5, formSet: 1 },
  { question: 'Read the excerpt from Booker T. Washington\'s Atlanta Exposition address (1895): "In all things that are purely social we can be as separate as the fingers, yet one as the hand in all things essential to mutual progress." Washington was proposing that', options: ['Black southerners demand an immediate end to all segregation laws', 'Black southerners leave the South for northern cities and factories', 'Black southerners delay equality demands and seek economic gains', 'Black southerners build a separate nation in Africa or the Caribbean'], correctAnswer: 2, explanation: 'Washington urged Black southerners to set aside demands for social equality for now and focus on vocational training and economic progress in cooperation with white southerners. He did not demand an end to segregation, he urged people to stay in the South, and he rejected emigration.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 6, formSet: 2 },
  { question: 'Read the excerpt from W. E. B. Du Bois\'s The Souls of Black Folk (1903): "It is a peculiar sensation, this double-consciousness, this sense of always looking at one\'s self through the eyes of others." In this passage Du Bois describes', options: ['the pride Black Americans felt in their dual African and American roots', 'the strain of judging oneself by the gaze of a society that scorns you', 'the confusion of formerly enslaved people about their new legal rights', 'the competition between rural and urban Black communities after 1900'], correctAnswer: 1, explanation: 'Double-consciousness names the inner conflict of measuring oneself by the contemptuous gaze of a white-dominated society while also being both Black and American. Du Bois presents it as a painful split rather than simple pride, and the passage is not about legal confusion or rural-urban rivalry.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 6, formSet: 1 },
  { question: 'In Southern Horrors (1892), Ida B. Wells built much of her case against lynching from reports printed in white southern newspapers. Using these sources strengthened her argument because', options: ['it drew on her opponents\' own accounts, making her evidence hard to dismiss', 'white newspapers were the only papers then printed anywhere in the South', 'those newspapers had openly called for federal anti-lynching legislation', 'it allowed her to avoid naming any specific victims or specific towns'], correctAnswer: 0, explanation: 'By citing white newspapers, Wells showed from her opponents\' own reporting that most lynchings had nothing to do with the alleged crimes used to justify them. Black newspapers also existed, white southern papers generally defended lynching, and her pamphlet named victims and places.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 6, formSet: 2 },
  { question: 'Which figure seized the Confederate ship Planter in 1862 and later represented South Carolina in Congress for five terms?', options: ['Robert Smalls', 'Hiram Revels', 'Booker T. Washington', 'Frederick Douglass'], correctAnswer: 0, explanation: 'Robert Smalls piloted the Planter out of Charleston harbor to the Union fleet and later served in Congress. Revels was a senator from Mississippi, Washington founded Tuskegee Institute, and Douglass held federal appointments but was never elected to Congress.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 7, formSet: 1 },
  { question: 'A student argues that African American leaders around 1900 disagreed sharply over how to respond to Jim Crow. Which pair of sources best supports that argument?', options: ['The Fourteenth Amendment and the Fifteenth Amendment', 'Field Order No. 15 and the Compromise of 1877', 'Plessy v. Ferguson and the Mississippi Plan of 1890', 'Washington\'s Atlanta address and Du Bois\'s Souls of Black Folk'], correctAnswer: 3, explanation: 'Washington\'s 1895 address urged accommodation and economic uplift, while Du Bois in 1903 criticized that approach and demanded political and civil rights, so together they show the debate. The other pairs are laws, orders, and rulings made mostly by white officials, not Black leaders\' competing strategies.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-reconstruction-jim-crow', part: 7, formSet: 2 },

  // ── aas-great-migration-harlem ──
  { question: 'Which was a PULL factor drawing Black southerners to northern cities during the Great Migration?', options: ['Boll weevils destroying the cotton crop', 'Mounting sharecropping debt to landlords', 'Industrial jobs opened by wartime labor shortages', 'Lynching and white mob violence'], correctAnswer: 2, explanation: 'Pull factors attract migrants to a destination, and World War I industrial demand, along with higher wages and the right to vote, drew Black workers north. The boll weevil, sharecropping debt, and lynching were push factors driving people out of the South.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 1, formSet: 1 },
  { question: 'In 1916 a Mississippi sharecropper owes more each year to the landowner\'s store, and the boll weevil has ruined his cotton. Historians would classify these conditions as', options: ['New Negro ideals', 'pull factors', 'push factors', 'Garveyite goals'], correctAnswer: 2, explanation: 'Debt peonage and crop failure were push factors that drove Black southerners away from the rural South. Pull factors are the attractions of the destination, and the New Negro and Garvey movements were cultural and political responses, not economic conditions.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 1, formSet: 2 },
  { question: 'How did Robert S. Abbott\'s Chicago Defender help spur the Great Migration?', options: ['It paid the train fare of every Black family that moved to Chicago.', 'It circulated only in Chicago and focused on local Black business news.', 'Pullman porters carried it south, spreading word of northern jobs.', 'It urged Black southerners to stay put and wait for reform at home.'], correctAnswer: 2, explanation: 'Abbott used Black Pullman porters to distribute the Defender across the South, where its job notices and attacks on Jim Crow encouraged readers to move north. It did not pay fares, its reach was national rather than local, and it actively promoted leaving the South.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 1, formSet: 1 },
  { question: 'Marcus Garvey\'s Universal Negro Improvement Association won mass support in the 1920s chiefly by promoting', options: ['integration through lawsuits in the federal courts', 'vocational training and patience on civil rights', 'interracial labor unions in northern factories', 'racial pride and Black economic independence'], correctAnswer: 3, explanation: 'Garvey\'s UNIA preached racial pride, economic independence through ventures like the Black Star Line, and "Back to Africa" nationalism. Court-based integration was the NAACP\'s strategy, vocational patience was Booker T. Washington\'s, and interracial unions were not Garvey\'s focus.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 1, formSet: 2 },
  { question: 'Why did northern employers recruit Black southern workers so heavily beginning around 1916?', options: ['War production surged just as European immigration was cut off.', 'Federal law required factories to hire workers from the South.', 'Northern unions invited Black workers to join on equal terms.', 'Southern states paid northern firms to take their farm laborers.'], correctAnswer: 0, explanation: 'World War I boosted industrial demand while cutting off the flow of European immigrants, so employers turned to Black southerners. No federal law mandated such hiring, most unions excluded Black workers, and southern planters tried to stop, not subsidize, the exodus.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 2, formSet: 1 },
  { question: 'The 1921 destruction of the Greenwood district of Tulsa, Oklahoma, is often cited in discussions of Black wealth because', options: ['city officials paid Black property owners in full for their losses', 'white mobs burned a prosperous Black business and residential area', 'the district was sold to developers in a peaceful federal land deal', 'Greenwood\'s residents relocated their businesses to Harlem intact'], correctAnswer: 1, explanation: 'White mobs destroyed Greenwood, a prosperous Black business community, killing an estimated 100 to 300 people and wiping out accumulated wealth that was never compensated. No officials paid for the losses, the destruction was violent rather than a land sale, and survivors did not relocate intact.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 2, formSet: 2 },
  { question: 'The "Red Summer" of 1919 refers to', options: ['a wave of white attacks on Black communities in more than two dozen cities', 'the spread of Communist Party organizing among Black factory workers', 'a nationwide strike by Black workers in northern steel and meatpacking', 'the summer in which the Harlem Renaissance\'s first art exhibits opened'], correctAnswer: 0, explanation: 'Red Summer was a season of anti-Black violence in more than 25 cities, including a Chicago riot that killed 38 people; "red" refers to bloodshed. It was not named for communism, it was not a Black-led strike, and it had nothing to do with art exhibitions.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 3, formSet: 1 },
  { question: 'What did the East St. Louis riot (1917) and the Chicago riot (1919) have in common?', options: ['Both began when Black soldiers mutinied against their white officers.', 'Both led Congress to pass a federal law making lynching a crime.', 'Both took place in Deep South towns that Black migrants were leaving.', 'Both grew from white hostility toward Black migrants seeking jobs.'], correctAnswer: 3, explanation: 'In both northern cities, white residents attacked Black newcomers they saw as competitors for work and homes, showing that migration did not escape racial violence. Neither began with a mutiny, Congress passed no federal anti-lynching law in this era, and both cities were destinations, not places migrants were leaving.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 3, formSet: 2 },
  { question: 'Historians link the Great Migration of 1910–1940 to the World War II era mainly because', options: ['the war ended the migration as most Black migrants returned to the South', 'defense jobs in the 1940s renewed the pull toward northern and western cities', 'the military forcibly relocated Black southerners to work in war plants', 'wartime laws barred Black workers from moving between states until 1945'], correctAnswer: 1, explanation: 'Wartime mobilization created new defense jobs that continued and expanded the migration\'s economic pull, including to West Coast cities. The war accelerated rather than ended the migration, movement was voluntary, and no law barred Black workers from moving.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 4, formSet: 1 },
  { question: 'How did the Great Migration lay groundwork for later civil rights gains?', options: ['Migrants regained the vote in northern cities and became a voting bloc.', 'Migrants persuaded southern states to repeal their poll taxes by 1925.', 'Migrants formed a separate political party that won control of Congress.', 'Migrants convinced the Supreme Court to overturn Plessy in the 1920s.'], correctAnswer: 0, explanation: 'Moving north restored the ballot to many Black Americans, and concentrated urban voters began electing Black officials and pressuring national parties. Southern poll taxes lasted for decades, no Black party controlled Congress, and Plessy stood until 1954.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 4, formSet: 2 },
  { question: 'The Great Depression marked a turning point for the Harlem Renaissance because', options: ['federal arts programs replaced private patrons with stable support right away', 'Black workers were hit hardest, and support for artists and publishers dried up', 'most of its writers moved to Paris and gave up writing about Black life', 'Harlem\'s population fell sharply as migrants returned to southern farms'], correctAnswer: 1, explanation: 'Black workers suffered disproportionately in the Depression, and the patronage and publishing money that sustained the Renaissance collapsed. New Deal arts programs came later and only partly filled the gap, writers did not abandon Black subjects, and Harlem\'s population did not empty out.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 5, formSet: 1 },
  { question: 'Alain Locke\'s anthology The New Negro (1925) signaled a change in how Black identity was presented. The "New Negro" was portrayed as', options: ['deferential to white patrons and grateful for all their support', 'rooted only in the rural South and wary of city life', 'focused on emigration and indifferent to American culture', 'self-assured and modern, voiced by its own writers and artists'], correctAnswer: 3, explanation: 'Locke\'s anthology of essays, fiction, poetry, and visual art presented a self-assured, modern Black identity articulated by Black writers and artists. It rejected deference, embraced the urban North alongside folk roots, and claimed a central place in American culture rather than turning away from it.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 5, formSet: 2 },
  { question: 'Read the excerpt from Langston Hughes, "The Negro Artist and the Racial Mountain" (1926): "We younger Negro artists who create now intend to express our individual dark-skinned selves without fear or shame. If white people are pleased we are glad. If they are not, it doesn\'t matter." Hughes is arguing that Black artists should', options: ['imitate European forms in order to win acceptance from critics', 'avoid racial themes so their work would appeal to all readers', 'depict their communities honestly, whatever others think', 'seek funding chiefly from white patrons who admired their work'], correctAnswer: 2, explanation: 'Hughes declared that Black artists should express Black experience honestly and independently of white approval, a manifesto of the Renaissance. He criticized imitation of white standards and the urge to avoid racial themes, and the passage rejects dependence on white opinion.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 6, formSet: 1 },
  { question: 'Zora Neale Hurston\'s Mules and Men (1935), based on her fieldwork in Florida and Louisiana, is most useful to historians as', options: ['a statistical survey of migration from the rural South', 'a record of Black southern folklore and speech', 'a political manifesto of Garvey\'s movement', 'a novel about nightlife in 1920s Harlem'], correctAnswer: 1, explanation: 'Hurston, trained in anthropology, collected folktales, songs, and hoodoo practices, preserving Black southern folk culture. The book is not a statistical study, a Garveyite manifesto, or a novel about Harlem.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 6, formSet: 2 },
  { question: 'Read the opening of Langston Hughes, "The Negro Speaks of Rivers" (1921): "I\'ve known rivers: / I\'ve known rivers ancient as the world and older than the flow of human blood in human veins." The poem connects Black identity most directly to', options: ['a deep heritage reaching back to Africa and beyond', 'the factory work that drew migrants to northern cities', 'the legal struggle against segregation in the courts', 'the political program of the Black Star Line'], correctAnswer: 0, explanation: 'The speaker claims the Euphrates, Congo, Nile, and Mississippi, linking Black identity to an ancient, diasporic heritage that predates slavery. The poem is not about factory work, litigation, or Garvey\'s shipping line.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 7, formSet: 1 },
  { question: 'Which Harlem Renaissance writer was also a trained folklorist and wrote Their Eyes Were Watching God (1937)?', options: ['Langston Hughes', 'Alain Locke', 'Nella Larsen', 'Zora Neale Hurston'], correctAnswer: 3, explanation: 'Zora Neale Hurston combined fiction with folklore collecting. Hughes was the movement\'s leading poet, Locke edited The New Negro, and Nella Larsen wrote the novels Quicksand and Passing.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-great-migration-harlem', part: 7, formSet: 2 },

  // ── aas-wwi-wwii-era ──
  { question: 'The Pittsburgh Courier\'s "Double V" campaign of 1942–1943 called for', options: ['victory in Europe and then victory over Japan', 'victory over fascism abroad and racism at home', 'victory in the war and in the 1944 election', 'victory for the Allies and for organized labor'], correctAnswer: 1, explanation: 'The Double V campaign linked the war against fascism overseas to the fight against racism in the United States. It was not about the sequence of military theaters, labor unions, or an election.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 1, formSet: 1 },
  { question: 'Executive Order 8802 (1941) is significant in African American history because it', options: ['struck down the white primary that Texas Democrats used to exclude Black voters', 'ordered the full desegregation of the U.S. Army, Navy, and Army Air Forces during the war', 'barred bias in defense industries, the first such federal step after Reconstruction', 'created the pilot-training program that produced the Tuskegee Airmen in Alabama'], correctAnswer: 2, explanation: 'Franklin Roosevelt\'s EO 8802 banned discrimination in defense industries and created the Fair Employment Practice Committee. Military desegregation came with Truman\'s EO 9981 in 1948, the white primary fell in Smith v. Allwright (1944), and the Tuskegee program was a separate War Department initiative.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 1, formSet: 2 },
  { question: 'A. Philip Randolph persuaded President Roosevelt to issue Executive Order 8802 in 1941 mainly by', options: ['winning a Supreme Court case against defense contractors', 'threatening a mass march of Black workers on Washington', 'negotiating a deal with the leaders of the AFL unions', 'calling a nationwide strike of all sleeping car porters'], correctAnswer: 1, explanation: 'Randolph\'s March on Washington Movement threatened to bring tens of thousands of Black protesters to the capital, and Roosevelt issued the order in exchange for calling off the march. No lawsuit, porters\' strike, or AFL deal produced the order.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 1, formSet: 1 },
  { question: 'The 369th Infantry Regiment, the "Harlem Hellfighters," is notable in World War I history for', options: ['spending 191 days in combat under French command', 'becoming the first racially integrated combat unit in the U.S. Army', 'flying bomber-escort missions over Italy and Germany', 'refusing to deploy overseas until the Army was desegregated'], correctAnswer: 0, explanation: 'Barred from fighting alongside white American troops, the 369th served with the French Army for 191 days and received the Croix de Guerre. It was a segregated unit, the bomber escorts were flown by the Tuskegee Airmen in World War II, and the regiment did deploy.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 1, formSet: 2 },
  { question: 'The Congress of Racial Equality (CORE), founded in Chicago in 1942, became known for pioneering', options: ['court challenges to segregated public schools', 'Black nationalist calls to resettle in Africa', 'nonviolent direct action against segregation', 'union organizing among sleeping car porters'], correctAnswer: 2, explanation: 'CORE used nonviolent direct action, including the 1947 Journey of Reconciliation that tested bus desegregation, which anticipated the 1961 Freedom Rides. School litigation was the NAACP\'s strategy, CORE was integrationist rather than emigrationist, and porters were organized by Randolph\'s union.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 2, formSet: 1 },
  { question: 'The Brotherhood of Sleeping Car Porters, founded in 1925, is significant because it', options: ['was a white-led union that opened its ranks to Black railroad workers', 'was a federal agency that set wages for workers on Pullman sleeping cars', 'was a fraternal lodge that avoided labor and political questions entirely', 'became the first Black-led union chartered by the AFL and a base for activism'], correctAnswer: 3, explanation: 'Under A. Philip Randolph, the Brotherhood became the first Black-led union recognized by the American Federation of Labor, and its network powered the March on Washington Movement. It was Black-led, it was a union rather than an agency, and it was deeply engaged in labor and civil rights politics.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 2, formSet: 2 },
  { question: 'Which statement correctly distinguishes Executive Order 8802 (1941) from Executive Order 9981 (1948)?', options: ['The first targeted defense-industry hiring; the second desegregated the armed forces.', 'The first desegregated the armed forces; the second targeted defense-industry hiring.', 'The first struck down white primaries; the second created the Freedmen\'s Bureau.', 'The first created the Tuskegee program; the second banned poll taxes nationwide.'], correctAnswer: 0, explanation: 'Roosevelt\'s 1941 order banned discrimination in defense industries, and Truman\'s 1948 order desegregated the military. White primaries fell in a court case, not by executive order, the Freedmen\'s Bureau dates from 1865, and poll taxes in federal elections ended with the Twenty-fourth Amendment in 1964.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 3, formSet: 1 },
  { question: 'The East St. Louis riot (1917) and the founding of the Brotherhood of Sleeping Car Porters (1925) both reflect', options: ['federal efforts to protect Black workers in northern factories', 'the decline of industrial jobs for Black workers after the war', 'the success of interracial unions in the American Federation of Labor', 'conflict and organizing over Black workers\' place in industrial labor'], correctAnswer: 3, explanation: 'In East St. Louis, white workers attacked Black migrants they saw as job competitors, and the Brotherhood organized Black workers to win fair treatment, so both center on Black labor in an industrial economy. The federal government did little to protect Black workers, industrial jobs grew in this era, and most AFL unions excluded Black workers.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 3, formSet: 2 },
  { question: 'Charles Hamilton Houston, a World War I veteran who became dean of Howard University\'s law school, links the war era to the civil rights movement because he', options: ['led the Brotherhood of Sleeping Car Porters in its 1941 campaign', 'designed the NAACP legal strategy that later produced Brown v. Board', 'founded CORE in Chicago to organize sit-ins against segregation', 'commanded the Tuskegee Airmen during their missions over Europe'], correctAnswer: 1, explanation: 'Houston built the NAACP\'s litigation campaign against segregation and trained Thurgood Marshall, who argued Brown v. Board of Education (1954). Randolph led the porters, CORE was founded by a group of activists in 1942, and Houston did not command the Tuskegee Airmen.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 4, formSet: 1 },
  { question: 'How does A. Philip Randolph\'s 1941 March on Washington Movement connect to the later civil rights movement?', options: ['The threatened 1941 march became the model for the 1963 national march.', 'The 1941 march took place and led directly to the Civil Rights Act of 1957.', 'The movement convinced Congress to desegregate the military during the war.', 'The movement merged with the UNIA to form a new Black nationalist party.'], correctAnswer: 0, explanation: 'Randolph\'s strategy of mass pressure on Washington resurfaced in the 1963 March on Washington, which he helped lead. The 1941 march was called off after EO 8802, military desegregation came by executive order in 1948, and the movement did not merge with Garvey\'s UNIA.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 4, formSet: 2 },
  { question: 'In Smith v. Allwright (1944), the Supreme Court', options: ['upheld the doctrine of "separate but equal" in schools', 'ordered the desegregation of the nation\'s armed forces', 'outlawed poll taxes in all federal elections nationwide', 'struck down the all-white Democratic primary in Texas'], correctAnswer: 3, explanation: 'Smith v. Allwright held that excluding Black voters from the Texas Democratic primary violated the Fifteenth Amendment, a major NAACP victory. Separate but equal was upheld in Plessy (1896), military desegregation came by executive order in 1948, and federal poll taxes were banned in 1964.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 5, formSet: 1 },
  { question: 'President Truman\'s Executive Order 9981 (1948) marked a decisive shift because it', options: ['banned job discrimination by wartime defense contractors', 'struck down whites-only primaries in southern states', 'began the desegregation of the U.S. armed forces', 'created the Fair Employment Practice Committee'], correctAnswer: 2, explanation: 'EO 9981 ordered equal treatment and opportunity in the military, which led to its desegregation by the mid-1950s, a change long demanded by Black veterans and activists. Banning defense-industry discrimination and creating the FEPC were the work of EO 8802 in 1941, and white primaries fell in Smith v. Allwright.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 5, formSet: 2 },
  { question: 'Records of the Tuskegee Airmen (332nd Fighter Group), who flew about 1,500 missions and compiled an outstanding bomber-escort record, were valuable to civil rights advocates because they', options: ['refuted claims that Black Americans could not serve in combat', 'showed the Army Air Forces had been integrated since World War I', 'proved that most Black servicemen opposed fighting in the war', 'documented that Black pilots served mainly as instructors at home'], correctAnswer: 0, explanation: 'The Airmen\'s operational record disproved military claims that Black men lacked the capacity for combat aviation, strengthening the case for desegregation. The Air Forces were segregated, Black servicemen fought despite discrimination, and the Airmen flew combat missions overseas.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 6, formSet: 1 },
  { question: 'Read the excerpt, adapted from James G. Thompson\'s 1942 letter to the Pittsburgh Courier, which inspired the Double V campaign: "Should I sacrifice my life to live half American?" Thompson\'s central question is', options: ['whether the United States should stay neutral in the war overseas', 'whether Black workers should leave defense plants for farm work', 'whether Black soldiers should seek service in the French Army', 'whether to fight for democracy abroad yet be denied it at home'], correctAnswer: 3, explanation: 'Thompson, a young cafeteria worker in Wichita, asked whether Black Americans should die for a democracy that treated them as second-class citizens, and the Courier turned his idea into the Double V campaign. The letter came after Pearl Harbor and did not urge neutrality, a return to farm work, or service with France.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 6, formSet: 2 },
  { question: 'A. Philip Randolph\'s 1941 March on Washington Movement memos are most useful as evidence of', options: ['Black leaders\' reliance on court cases rather than protest', 'Black leaders using the threat of mass protest to win federal action', 'Black workers\' support for staying out of the war entirely', 'Black leaders\' alliance with southern Democrats in Congress'], correctAnswer: 1, explanation: 'The memos show Randolph mobilizing a threatened mass march to pressure Roosevelt, which produced EO 8802. They document direct-action pressure rather than litigation, they did not oppose the war effort, and southern Democrats were the movement\'s opponents.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 6, formSet: 1 },
  { question: 'Which leader founded the Brotherhood of Sleeping Car Porters in 1925?', options: ['A. Philip Randolph', 'Charles Hamilton Houston', 'Marcus Garvey', 'W. E. B. Du Bois'], correctAnswer: 0, explanation: 'A. Philip Randolph organized and led the Brotherhood of Sleeping Car Porters. Houston was a lawyer and legal strategist, Garvey led the UNIA, and Du Bois edited the NAACP\'s magazine, The Crisis.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 7, formSet: 2 },
  { question: 'A student argues that Black military service in World War II helped undermine segregation. Which pair of evidence best supports that argument?', options: ['The East St. Louis riot and the Red Summer of 1919', 'The Harlem Hellfighters and the Croix de Guerre', 'The Brotherhood of Sleeping Car Porters and the AFL', 'The Tuskegee Airmen\'s record and Executive Order 9981'], correctAnswer: 3, explanation: 'The Tuskegee Airmen disproved claims about Black combat ability, and Truman desegregated the armed forces in 1948, linking wartime service to the end of military segregation. The riots and the Hellfighters belong to the World War I era, and the porters\' union concerns labor rather than military service.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-wwi-wwii-era', part: 7, formSet: 1 },

  // ── aas-practice-freedom ──
  { question: 'Freedom\'s Journal, launched in New York in 1827, holds an important place in the history of the Black press as', options: ['the first paper owned and edited by African Americans', 'the Chicago paper that urged southerners to move north', 'the weekly that launched the wartime Double V campaign', 'the abolitionist weekly edited by William Lloyd Garrison'], correctAnswer: 0, explanation: 'Freedom\'s Journal was the first African American-owned and -edited newspaper, letting Black writers speak for themselves. Garrison\'s Liberator began in 1831, the Chicago Defender promoted migration, and the Pittsburgh Courier ran the Double V campaign.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 1, formSet: 1 },
  { question: 'Historians describe the churches, colleges, newspapers, and women\'s clubs that Black Americans built after emancipation as a "counter-public" because these institutions', options: ['were funded and managed mainly by the federal government', 'depended on white philanthropists to choose their leaders', 'gave the community its own arenas for debate and leadership', 'existed mostly to prepare Black families to emigrate abroad'], correctAnswer: 2, explanation: 'This institutional world gave Black communities their own spaces to debate, organize, and train leaders outside white-controlled public life. The institutions were built and run by Black Americans rather than the federal government or white patrons, and they served communities at home rather than emigration.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 1, formSet: 2 },
  { question: 'Madam C. J. Walker\'s haircare company belongs in a unit on Black institution-building mainly because it', options: ['depended on loans from white banks to stay in operation', 'sold its products only to white customers in the North', 'was owned by the federal government after Walker\'s death', 'created wealth and trained thousands of women as agents'], correctAnswer: 3, explanation: 'Walker built a business serving Black women and trained some 40,000 Black women as sales agents, creating income and economic independence. The company was Black-owned, served Black customers, and was never a government enterprise.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 1, formSet: 1 },
  { question: 'Mary McLeod Bethune\'s role as a coordinator of Franklin Roosevelt\'s informal "Black Cabinet" illustrates', options: ['the exclusion of all Black advisers from New Deal agencies', 'Black leaders gaining a voice in shaping New Deal policy', 'Bethune\'s opposition to federal programs for Black youth', 'the end of segregation in federal agencies by the 1930s'], correctAnswer: 1, explanation: 'Bethune and other Black officials advised the Roosevelt administration and pressed for fairer treatment of Black Americans in New Deal programs. Their presence contradicts total exclusion, Bethune herself directed Negro affairs for the National Youth Administration, and federal agencies remained segregated.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 1, formSet: 2 },
  { question: 'Carter G. Woodson founded the Association for the Study of Negro Life and History (1915) and Negro History Week (1926) chiefly to', options: ['train Black teachers in vocational and agricultural skills', 'lobby Congress to pass a federal anti-lynching law', 'build scholarship on the Black past and teach it widely', 'recruit settlers for Marcus Garvey\'s colony in Liberia'], correctAnswer: 2, explanation: 'Woodson institutionalized Black historical scholarship and promoted its teaching; Negro History Week later became Black History Month. Vocational training was Tuskegee\'s focus, anti-lynching lobbying was led by the NAACP, and Woodson did not recruit for Garvey.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 2, formSet: 1 },
  { question: 'Which of these historically Black institutions was founded in the decade right after the Civil War?', options: ['Howard University', 'Tuskegee Institute', 'Spelman College', 'Bethune-Cookman College'], correctAnswer: 0, explanation: 'Howard University was founded in 1867, during Reconstruction. Tuskegee and Spelman both date from 1881, and Bethune-Cookman grew out of the school Mary McLeod Bethune opened in 1904.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 2, formSet: 2 },
  { question: 'The motto of the National Association of Colored Women (1896), "Lifting as We Climb," expressed the idea that', options: ['Black women should leave reform work to men and churches', 'Black women should seek success for themselves in business', 'Black women should focus on winning the vote before all else', 'Black women who advanced should raise their communities with them'], correctAnswer: 3, explanation: 'The NACW\'s clubwomen saw their own progress as tied to uplifting their communities through schools, kindergartens, and social services. They took on reform work themselves, rejected purely individual success, and pursued suffrage alongside many other goals.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 3, formSet: 1 },
  { question: 'Which contrast between Tuskegee Institute (1881) and the NAACP (1909) is accurate?', options: ['Tuskegee fought segregation in court; the NAACP trained farmers and tradespeople.', 'Tuskegee was led by Du Bois; the NAACP was led by Booker T. Washington.', 'Tuskegee stressed vocational uplift; the NAACP pursued civil rights through law and protest.', 'Tuskegee urged emigration to Africa; the NAACP promoted Black nationalism and separatism.'], correctAnswer: 2, explanation: 'Under Booker T. Washington, Tuskegee emphasized vocational education and economic self-help, while the NAACP, founded by Du Bois, Wells, Ovington, and others, challenged segregation and disfranchisement through lawsuits and agitation. The other contrasts reverse the institutions\' roles or misidentify them.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 3, formSet: 2 },
  { question: 'Why do historians call Black churches, colleges, and civic groups the "staging grounds" of the postwar civil rights movement?', options: ['They kept apart from politics to protect their tax-exempt status.', 'They were run by federal agencies that directed protest campaigns.', 'They opposed protest and urged members to wait for court rulings.', 'They supplied meeting places and trained leaders for mass protest.'], correctAnswer: 3, explanation: 'Churches hosted mass meetings, colleges produced student activists, and civic groups provided networks and leaders, so these institutions powered campaigns such as the Montgomery Bus Boycott. They were politically engaged, independent of federal control, and central to protest rather than opposed to it.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 4, formSet: 1 },
  { question: 'Howard University\'s law school under Charles Hamilton Houston shows how HBCUs fed the civil rights movement. Which development best demonstrates this?', options: ['Its faculty drafted the Atlanta Compromise for Booker T. Washington.', 'It trained lawyers such as Thurgood Marshall who litigated against segregation.', 'It became the headquarters of the Black Panther Party in the 1960s.', 'It refused to admit students who took part in civil rights protests.'], correctAnswer: 1, explanation: 'Houston turned Howard Law into a training ground for civil rights lawyers, including Thurgood Marshall, who argued Brown v. Board. Washington wrote his own 1895 speech, the Black Panthers were founded in Oakland, and Howard did not bar activist students.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 4, formSet: 2 },
  { question: 'Rube Foster\'s Negro National League, which began play in 1920, is best understood as', options: ['the first racially integrated professional baseball league', 'a federal program to employ Black athletes in the Depression', 'a Black-owned sports enterprise created within segregation', 'a protest movement demanding entry into the major leagues'], correctAnswer: 2, explanation: 'Barred from white professional baseball, Black entrepreneurs led by Foster built their own league, part of the wider world of Black-owned institutions. It was segregated by necessity rather than integrated, it predated the New Deal, and it was a business rather than a protest campaign.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 5, formSet: 1 },
  { question: 'Mary McLeod Bethune founded the National Council of Negro Women in 1935 in order to', options: ['unite existing Black clubs and sororities behind one voice', 'replace the NAACP as the main civil rights litigator', 'organize Black domestic workers into an AFL union', 'run a chain of schools for Black girls in Florida'], correctAnswer: 0, explanation: 'The NCNW brought together existing Black women\'s organizations so they could press for policy change as a united national body. It did not take over the NAACP\'s legal work, it was not a labor union, and Bethune\'s school in Daytona was a separate project begun in 1904.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 5, formSet: 2 },
  { question: 'Read the excerpt from Carter G. Woodson, The Mis-Education of the Negro (1933): "The same educational process which inspires and stimulates the oppressor with the thought that he is everything . . . depresses and crushes at the same time the spark of genius in the Negro." Woodson argues that', options: ['Black students needed more vocational training and less academic study', 'segregated schools for Black students should be closed down at once', 'Black teachers were less qualified than white teachers of the era', 'schooling that erased Black achievement taught Black students inferiority'], correctAnswer: 3, explanation: 'Woodson charged that curricula built around white achievement and silent about Black history taught Black students to believe in their own inferiority. His critique concerns the content of education rather than vocational balance, school closures, or teacher qualifications.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 6, formSet: 1 },
  { question: 'Ida B. Wells wrote her autobiography, Crusade for Justice, late in life, and it was published in 1970, long after her death in 1931. A historian using it as a source should consider that', options: ['it was written by her opponents to discredit her anti-lynching work', 'it contains only statistics on lynching with no personal account', 'it looks back through memory and the author\'s view of her role', 'it was produced by a government commission investigating lynching'], correctAnswer: 2, explanation: 'As a retrospective memoir, Crusade for Justice reflects memory and Wells\'s interpretation of her own activism, so it is valuable for her perspective but should be checked against sources from the time. Wells wrote it herself, it is a narrative rather than a statistical report, and no government body produced it.', difficulty: 'hard', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 6, formSet: 2 },
  { question: 'The archives of the Pittsburgh Courier, the largest-circulation Black weekly of the early twentieth century, would be most useful for studying', options: ['debates among white southern legislators', 'the views and activism of its readers', 'federal court rulings on school segregation', 'European reactions to American jazz music'], correctAnswer: 1, explanation: 'A widely read Black newspaper records what Black readers and journalists thought and organized around, such as the Double V campaign. It would not be the best source for white legislators\' internal debates, court records, or European opinion.', difficulty: 'medium', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 6, formSet: 1 },
  { question: 'Who founded Negro History Week in 1926, the forerunner of Black History Month?', options: ['W. E. B. Du Bois', 'Alain Locke', 'Booker T. Washington', 'Carter G. Woodson'], correctAnswer: 3, explanation: 'Carter G. Woodson created Negro History Week and founded the Association for the Study of Negro Life and History. Du Bois co-founded the NAACP, Locke edited The New Negro, and Washington led Tuskegee Institute.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 7, formSet: 2 },
  { question: 'Which figure was an anti-lynching crusader, a founder of the NAACP in 1909, and a suffragist?', options: ['Ida B. Wells', 'Mary McLeod Bethune', 'Madam C. J. Walker', 'Zora Neale Hurston'], correctAnswer: 0, explanation: 'Ida B. Wells documented lynching, helped found the NAACP, and campaigned for women\'s suffrage. Bethune was an educator and New Deal adviser, Walker built a haircare business, and Hurston was a novelist and folklorist.', difficulty: 'easy', domain: 'practice-freedom', topicSlug: 'aas-practice-freedom', part: 7, formSet: 1 },

  // ════════════════ Unit 4 — movements-debates ════════════════

  // ── aas-civil-rights-movement ──
  { question: 'In Brown v. Board of Education (1954), a unanimous Supreme Court ruled that', options: ['separate schools were lawful so long as their facilities were equal', 'segregated seating on city buses violated the Fourteenth Amendment', 'state-mandated segregation of public schools was unconstitutional', 'literacy tests for voters violated the Fifteenth Amendment'], correctAnswer: 2, explanation: 'Brown held that segregated public schools were inherently unequal, overturning Plessy v. Ferguson in public education. "Separate but equal" was Plessy\'s doctrine, bus segregation fell in Browder v. Gayle (1956), and literacy tests were addressed by the Voting Rights Act.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 1, formSet: 1 },
  { question: 'Ella Baker\'s philosophy of organizing, which shaped the Student Nonviolent Coordinating Committee, emphasized', options: ['developing grassroots leaders instead of one leader', 'building the movement around a single charismatic minister', 'winning change mainly through federal court litigation', 'organizing armed self-defense units in rural communities'], correctAnswer: 0, explanation: 'Baker championed group-centered, bottom-up leadership and encouraged students to found an independent SNCC in 1960. She criticized the reliance on a single charismatic leader that she saw in the SCLC, and SNCC focused on direct action and voter registration rather than litigation or armed units.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 1, formSet: 2 },
  { question: 'Historians stress that Rosa Parks was a trained NAACP chapter secretary when she refused to give up her bus seat on December 1, 1955. This detail most directly challenges the view that', options: ['the Montgomery boycott was organized mostly by local Black women', 'the boycott lasted for more than a year before it succeeded', 'the NAACP had little presence in Alabama during the 1950s', 'her protest was a spontaneous act by a tired, apolitical worker'], correctAnswer: 3, explanation: 'Parks was an experienced activist, so her refusal was a principled act of resistance rather than a spur-of-the-moment gesture of fatigue. Local Black women did organize the boycott, her role shows the NAACP was active in Alabama, and the boycott did last 381 days.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 1, formSet: 1 },
  { question: 'Section 5 of the Voting Rights Act of 1965 required certain states and counties with histories of discrimination to', options: ['hold all of their elections under the supervision of federal troops', 'register every adult citizen automatically when they turned twenty-one', 'abolish poll taxes in state elections within one year of passage', 'obtain federal approval before making any change to election rules'], correctAnswer: 3, explanation: 'Section 5\'s preclearance requirement meant covered jurisdictions needed federal approval for any change to voting rules, blocking new discriminatory devices. The act sent federal examiners rather than troops, it did not create automatic registration, and the Supreme Court struck down state poll taxes in a separate 1966 case.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 1, formSet: 2 },
  { question: 'The Greensboro sit-ins of February 1960 mattered to the movement mainly because', options: ['student protest spread to dozens of cities and led to the founding of SNCC', 'Congress immediately passed a law desegregating lunch counters nationwide', 'they persuaded the NAACP to abandon its strategy of litigation entirely', 'they were the first protests ever organized by college students in the South'], correctAnswer: 0, explanation: 'Four students\' sit-in at a Woolworth\'s counter sparked protests in some 55 cities in 13 states and the founding of SNCC in April 1960. Public accommodations were not desegregated by law until 1964, the NAACP kept litigating, and students had protested before.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 2, formSet: 1 },
  { question: 'How did President Eisenhower respond in 1957 when Arkansas officials and mobs blocked nine Black students from entering Little Rock\'s Central High School?', options: ['He ordered the students to transfer to a Black high school.', 'He asked Congress to delay school desegregation for a decade.', 'He federalized the Arkansas Guard and sent in Army troops.', 'He left the dispute to Arkansas courts and the state governor.'], correctAnswer: 2, explanation: 'Eisenhower federalized the Arkansas National Guard and deployed Army troops to escort the Little Rock Nine, enforcing Brown with federal power. He did not order a transfer, seek a delay from Congress, or leave the matter to state officials, who were the ones defying the courts.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 2, formSet: 2 },
  { question: 'The Montgomery Bus Boycott of 1955–1956 ended in victory after 381 days when', options: ['the city council voluntarily ended segregated seating', 'the bus company went bankrupt and was sold to the city', 'Browder v. Gayle declared segregated buses unconstitutional', 'Congress passed a law requiring desegregated city transit'], correctAnswer: 2, explanation: 'The boycott held until the federal courts ruled in Browder v. Gayle that bus segregation was unconstitutional, a ruling the Supreme Court affirmed. Montgomery officials resisted to the end, the bus company survived, and Congress passed no transit law then.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 3, formSet: 1 },
  { question: 'Why did the 1963 Birmingham campaign build national pressure for a civil rights law?', options: ['Televised images of fire hoses and police dogs turned on children shocked viewers.', 'Birmingham\'s officials agreed at once to desegregate the city and asked other cities to follow.', 'Armed protesters took control of downtown Birmingham and forced Congress to respond.', 'The campaign avoided media attention and relied on quiet negotiations with business owners.'], correctAnswer: 0, explanation: 'Public Safety Commissioner Bull Connor\'s attacks on young marchers were broadcast nationwide, moving public opinion and prompting President Kennedy to propose what became the Civil Rights Act of 1964. City officials resisted rather than complied, the protests were nonviolent, and organizers deliberately sought media coverage.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 3, formSet: 2 },
  { question: 'By 1966 some SNCC activists who had led nonviolent campaigns in the Deep South embraced the call for Black Power. Which factor best helps explain this shift?', options: ['Repeated violence and weak federal protection led them to question integration as a goal.', 'The Civil Rights Act of 1964 had already ended discrimination in the North and South.', 'The SCLC ordered SNCC to adopt a new approach after the March on Washington in 1963.', 'Southern voters had elected large numbers of Black officials by 1965, ending the need for protest.'], correctAnswer: 0, explanation: 'Beatings, murders, and slow federal action during campaigns such as Freedom Summer led younger activists to challenge the integrationist, nonviolent strategy and stress self-determination. Discrimination persisted after 1964, SNCC was independent of the SCLC, and Black officeholding in the South was still minimal in 1965.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 4, formSet: 1 },
  { question: 'Which statement best describes how the Civil Rights Movement and the Black Power movement were related?', options: ['Black Power was a separate movement with no ties to earlier organizations.', 'Black Power was organized by the federal government to replace the SCLC.', 'Black Power emerged inside groups like SNCC and challenged integrationist goals.', 'Black Power adopted the SCLC\'s program without changing any of its aims.'], correctAnswer: 2, explanation: 'Black Power grew out of the movement itself, as SNCC chair Stokely Carmichael\'s 1966 call shows, and it questioned integration as the goal. It had deep organizational roots, it was not a government creation, and it departed sharply from the SCLC\'s aims.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 4, formSet: 2 },
  { question: 'Which statement correctly distinguishes the Civil Rights Act of 1964 from the Voting Rights Act of 1965?', options: ['The 1964 act targeted voting barriers; the 1965 act banned job discrimination.', 'The 1964 act desegregated the military; the 1965 act repealed the poll tax amendment.', 'The 1964 act ended school segregation; the 1965 act created the NAACP legal fund.', 'The 1964 act banned bias in public places and jobs; the 1965 act targeted voting barriers.'], correctAnswer: 3, explanation: 'The Civil Rights Act outlawed discrimination in public accommodations and employment (Title VII), while the Voting Rights Act attacked literacy tests and other voting barriers with federal examiners and preclearance. Reversing the two acts gets both wrong, Brown ended legal school segregation, the military was desegregated in 1948, and no poll tax amendment was repealed.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 5, formSet: 1 },
  { question: 'The Selma-to-Montgomery marches of 1965 marked a turning point because', options: ['marchers seized the Alabama capitol and forced new state elections', 'televised "Bloody Sunday" violence built support for a voting law', 'Governor Wallace welcomed the marchers and endorsed federal voting rights', 'the marches ended the movement\'s reliance on nonviolent protest tactics'], correctAnswer: 1, explanation: 'State troopers\' attack on marchers at the Edmund Pettus Bridge was broadcast nationally, and within months Congress passed the Voting Rights Act. The marchers did not seize the capitol, Wallace opposed them, and the campaign was a model of nonviolent protest.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 5, formSet: 2 },
  { question: 'Read the excerpt, adapted from Martin Luther King Jr.\'s "Letter from Birmingham Jail" (1963): "The Negro\'s great stumbling block in his stride toward freedom is not the Ku Klux Klanner, but the white moderate, who is more devoted to \'order\' than to justice." King\'s point is that', options: ['the Klan posed no real danger to Black activists in Alabama', 'well-meaning whites who urged patience and calm stalled change', 'white moderates were the movement\'s most reliable financial supporters', 'the movement should give up direct action and rely on negotiations'], correctAnswer: 1, explanation: 'King argued that well-meaning moderates who urged patience and condemned protest as disorderly were a greater obstacle than open racists. He did not dismiss the Klan\'s violence, he criticized rather than praised moderates, and the letter defends direct action.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 6, formSet: 1 },
  { question: 'Fannie Lou Hamer\'s nationally televised testimony before the 1964 Democratic National Convention\'s Credentials Committee mattered because it', options: ['announced that the Mississippi Freedom Democrats would leave politics', 'showed viewers the violence used to keep Black Mississippians from voting', 'persuaded the convention to seat every member of the Freedom delegation', 'endorsed the all-white Mississippi delegation as a fair compromise'], correctAnswer: 1, explanation: 'Hamer described being evicted and beaten for trying to register to vote, bringing Mississippi\'s repression into American living rooms. The Freedom Democrats kept organizing, the convention offered only two at-large seats, which they rejected, and Hamer was challenging the all-white delegation.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 6, formSet: 2 },
  { question: 'King wrote "Letter from Birmingham Jail" in reply to a published statement by eight white Alabama clergymen who called the protests "unwise and untimely." Knowing this audience helps explain why King', options: ['avoided any reference to scripture or to religious leaders', 'framed his case in religious and moral terms for fellow ministers', 'addressed his argument mainly to members of the Black Panther Party', 'wrote in legal language meant for federal judges hearing his case'], correctAnswer: 1, explanation: 'Answering fellow ministers, King drew on scripture, theology, and moral philosophy to justify direct action and civil disobedience. He used religious references heavily, the Panthers did not exist until 1966, and the letter is a moral argument rather than a legal brief.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 6, formSet: 1 },
  { question: 'Who served as chief counsel for the NAACP Legal Defense Fund in Brown v. Board and became the first Black Supreme Court justice in 1967?', options: ['John Lewis', 'Charles Hamilton Houston', 'Martin Luther King Jr.', 'Thurgood Marshall'], correctAnswer: 3, explanation: 'Thurgood Marshall argued Brown and was appointed to the Supreme Court in 1967. Houston was his mentor and died in 1950, King led the SCLC, and Lewis chaired SNCC and later served in Congress.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 7, formSet: 2 },
  { question: 'Which SNCC chairman was beaten while leading marchers across the Edmund Pettus Bridge on "Bloody Sunday" in March 1965?', options: ['Stokely Carmichael', 'John Lewis', 'Bayard Rustin', 'Medgar Evers'], correctAnswer: 1, explanation: 'John Lewis, then chairman of SNCC, suffered a fractured skull on Bloody Sunday. Carmichael succeeded him as chair in 1966, Rustin organized the 1963 March on Washington, and Evers was murdered in Mississippi in 1963.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-civil-rights-movement', part: 7, formSet: 1 },

  // ── aas-black-power-beyond ──
  { question: 'Which leader brought the slogan "Black Power" to national attention at a June 1966 rally in Greenwood, Mississippi?', options: ['Malcolm X', 'Stokely Carmichael', 'Huey P. Newton', 'Martin Luther King Jr.'], correctAnswer: 1, explanation: 'SNCC chairman Stokely Carmichael (later Kwame Ture) raised the cry during the 1966 March Against Fear, reframing the movement. Malcolm X had been assassinated in 1965, Newton co-founded the Panthers that October, and King was uneasy with the slogan.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 1, formSet: 1 },
  { question: 'The Black Panther Party called its free breakfasts, free health clinics, and sickle-cell anemia screenings "survival programs" because they were meant to', options: ['serve as federal programs that the Panthers ran under contract', 'meet daily needs the government neglected and build local support', 'help Black families move into white suburbs in large numbers', 'raise money to buy weapons for armed actions against police'], correctAnswer: 1, explanation: 'Survival programs supplied food and health care that communities lacked, demonstrating self-determination and winning grassroots support for the party. They were Panther-run rather than federally funded, they were service programs rather than arms fundraisers, and they aimed at community control rather than suburban integration.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 1, formSet: 2 },
  { question: 'The Black Arts Movement associated with Amiri Baraka, Sonia Sanchez, and Larry Neal is best described as', options: ['a New Deal program that hired Black artists for public murals', 'a 1960s revival of the Harlem Renaissance led by Alain Locke', 'Black Power\'s cultural wing, creating art for Black audiences', 'an integrationist effort to place Black performers on Broadway'], correctAnswer: 2, explanation: 'The Black Arts Movement was Black Power\'s cultural wing, creating poetry, theater, and visual art rooted in and addressed to Black communities. It was not a New Deal program, Locke died in 1954, and it rejected integrationist aims in favor of a separate Black aesthetic.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 1, formSet: 1 },
  { question: 'After his 1964 pilgrimage to Mecca and his break with the Nation of Islam, Malcolm X increasingly', options: ['embraced nonviolence and joined the Southern Christian Leadership Conference', 'framed the Black freedom struggle as an international human rights cause', 'withdrew from politics to focus entirely on religious study in Egypt', 'urged Black Americans to vote for Barry Goldwater in the 1964 election'], correctAnswer: 1, explanation: 'Malcolm X founded the Organization of Afro-American Unity in 1964 and sought to bring Black Americans\' grievances before the world as human rights violations. He never joined the SCLC or adopted strict nonviolence, he stayed politically active until his assassination in February 1965, and he did not endorse Goldwater.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 1, formSet: 2 },
  { question: 'The 1965 uprising in the Watts neighborhood of Los Angeles, which left 34 people dead, signaled that', options: ['the Voting Rights Act had resolved the main grievances of urban Black residents', 'the civil rights movement had shifted its center from cities to the rural South', 'Black Power organizations had begun planning armed revolts in western cities', 'laws aimed at southern segregation left urban poverty and policing unaddressed'], correctAnswer: 3, explanation: 'Watts erupted days after the Voting Rights Act was signed, showing that police abuse, unemployment, and housing discrimination in northern and western cities were untouched by laws aimed at southern Jim Crow. The uprising grew out of a traffic stop rather than a plan, and it pointed the movement toward cities, not away from them.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 2, formSet: 1 },
  { question: 'The Black Panther Party was founded in Oakland, California, in October 1966 by', options: ['Stokely Carmichael and Charles Hamilton', 'Fred Hampton and Angela Davis', 'Huey P. Newton and Bobby Seale', 'Malcolm X and Elijah Muhammad'], correctAnswer: 2, explanation: 'Newton and Seale founded the party and wrote its Ten-Point Program. Carmichael and Hamilton co-wrote the book Black Power, Hampton led the Illinois chapter and Davis was a scholar-activist, and Malcolm X and Elijah Muhammad were Nation of Islam leaders.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 2, formSet: 2 },
  { question: 'Tommie Smith and John Carlos raised gloved fists on the medal stand at the 1968 Mexico City Olympics. Their gesture is best understood as', options: ['a protest tying Black athletes to the global human rights cause', 'a salute celebrating the U.S. team\'s record medal count that year', 'a demonstration against Mexico\'s decision to host the Olympic Games', 'a call for American athletes to boycott all future Olympic competitions'], correctAnswer: 0, explanation: 'Part of the Olympic Project for Human Rights, the protest used a global stage to condemn racism and poverty. It was a political protest rather than a celebration, it targeted American racism rather than Mexico, and it did not launch a permanent boycott.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 3, formSet: 1 },
  { question: 'Which statement best compares the Watts uprising (1965) and the founding of the Black Panther Party (1966)?', options: ['Both were planned by SNCC; Watts targeted Congress, and the Panthers targeted state voting laws.', 'Both were led by Malcolm X; Watts began in Harlem, and the Panthers began in Chicago.', 'Both ended segregation in California; Watts won a court case, and the Panthers won elections.', 'Both answered police abuse and neglect; Watts was a revolt, and the Panthers a disciplined group.'], correctAnswer: 3, explanation: 'Police abuse and neglect of Black urban neighborhoods fueled both, but Watts was a spontaneous uprising while the Panthers built a disciplined organization with a written program. SNCC did not plan either, Malcolm X was dead by 1965, and neither event won a court case or elections.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 3, formSet: 2 },
  { question: 'Black Power both extended and criticized the earlier civil rights movement. Which example shows Black Power EXTENDING the earlier struggle rather than criticizing it?', options: ['Rejecting integration into white institutions as the main goal', 'Questioning nonviolence as a binding strategy for all activists', 'Organizing independent electoral strength at the 1972 Gary convention', 'Asking white members to leave leadership roles in SNCC'], correctAnswer: 2, explanation: 'The Gary convention carried forward the civil rights goal of political participation, now pursued through independent Black organizing. Rejecting integration, questioning nonviolence, and removing white members from SNCC leadership were critiques of the earlier movement\'s strategy.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 4, formSet: 1 },
  { question: 'Which decision by SNCC in 1966–1967 reflected the Black Power critique of integrationist strategy?', options: ['It asked white members to organize in white communities instead of SNCC.', 'It merged with the NAACP to focus entirely on litigation in federal courts.', 'It dissolved itself so that its members could join the Democratic Party.', 'It adopted the SCLC\'s policy of following a single national leader.'], correctAnswer: 0, explanation: 'Under the Black Power banner, SNCC voted to have Black people lead Black organizations and urged white allies to fight racism in white communities. SNCC did not merge with the NAACP, did not dissolve to join the Democrats, and had long rejected single-leader organizing.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 4, formSet: 2 },
  { question: 'The Black Panther Party\'s Free Breakfast Program, which by 1969 was feeding thousands of children each day, is historically significant partly because it', options: ['was paid for by the FBI as part of a community outreach effort', 'replaced public schools in Oakland with Panther-run academies', 'was limited to the children of party members and their families', 'pressured officials to expand federal morning meals in schools'], correctAnswer: 3, explanation: 'The program\'s reach embarrassed officials and helped push the expansion of the federal School Breakfast Program. The FBI worked to disrupt the Panthers rather than fund them, the program fed children in public schools\' neighborhoods without replacing schools, and it was open to the community.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 5, formSet: 1 },
  { question: 'The 1971 uprising at Attica prison in New York is significant in the history of Black Power because it', options: ['ended with the state granting every demand prisoners had made', 'was organized by the Gary convention to protest voting laws', 'joined militant politics to the prisoners\' rights cause', 'proved that prisons in the North were free of racial tension'], correctAnswer: 2, explanation: 'Attica\'s rebels, many influenced by Black Power, demanded humane conditions and political rights, joining the two struggles; the state\'s retaking of the prison killed dozens. Most demands were refused, the Gary convention came a year later, and the uprising exposed rather than disproved racial tension.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 5, formSet: 2 },
  { question: 'The 1972 National Black Political Convention in Gary, Indiana, where about 10,000 participants drafted a National Black Political Agenda, signaled a shift in Black Power toward', options: ['electing officials and pursuing shared goals', 'armed revolution against the federal government', 'emigration to newly independent African nations', 'withdrawal from all forms of political activity'], correctAnswer: 0, explanation: 'Gary brought nationalists, elected officials, and activists together to pursue power through elections and policy, reflecting the growth of Black officeholding in the 1970s. It did not call for armed revolution, mass emigration, or withdrawal from politics.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 5, formSet: 1 },
  { question: 'Read the excerpt from the Black Panther Party\'s Ten-Point Program (1966): "We want freedom. We want power to determine the destiny of our Black Community. . . . We want an immediate end to police brutality and murder of Black people." These demands reflect', options: ['a plan to dissolve Black neighborhoods into white suburbs', 'support for the federal government\'s urban renewal agenda', 'a call for Black Americans to leave the country for Africa', 'local self-rule and safety from abusive officers'], correctAnswer: 3, explanation: 'The program demanded community control over Black neighborhoods\' future and an end to police abuse, core Black Power goals. It sought power within Black communities rather than dispersal into suburbs, it criticized rather than backed federal urban policy, and it did not call for emigration.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 6, formSet: 2 },
  { question: 'In Black Power (1967), Stokely Carmichael and Charles V. Hamilton distinguished individual racism from "institutional racism." By the second term they meant', options: ['open acts of bigotry carried out by individual white people', 'laws that explicitly named race as a reason for unequal treatment', 'discrimination built into the routine workings of established systems', 'prejudice that Black organizations held toward white supporters'], correctAnswer: 2, explanation: 'Institutional racism describes inequality produced by the normal operation of housing, schools, banks, and other systems, even without individual bigots. Individual acts are what the authors contrasted it with, explicitly racial laws are de jure discrimination, and the term did not refer to Black organizations.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 6, formSet: 1 },
  { question: 'Angela Davis\'s Women, Race & Class (1981) is most useful as a source for studying', options: ['how Black feminist thought linked several systems of oppression', 'the voting records of Black members of Congress in the 1970s', 'the founding of the Black Panther Party in Oakland in 1966', 'federal court rulings on school busing in northern cities'], correctAnswer: 0, explanation: 'Davis\'s book synthesizes Black feminism, Marxism, and abolitionism, analyzing how race, gender, and class oppression intersect. It is a work of theory and history, not a record of congressional votes, Panther founding documents, or busing cases.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 6, formSet: 2 },
  { question: 'Which Illinois Black Panther leader built the original Rainbow Coalition and was killed in a December 1969 raid by Chicago police working with the FBI?', options: ['Huey P. Newton', 'Bobby Seale', 'Stokely Carmichael', 'Fred Hampton'], correctAnswer: 3, explanation: 'Fred Hampton, chair of the Illinois Black Panther Party, organized a multiracial Rainbow Coalition and was killed in his bed on December 4, 1969. Newton and Seale founded the party in Oakland, and Carmichael led SNCC.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 7, formSet: 1 },
  { question: 'Which philosopher was fired from UCLA in 1969 for Communist Party membership, acquitted of criminal charges in 1972, and later became a leading voice for prison abolition?', options: ['Angela Davis', 'Audre Lorde', 'Sonia Sanchez', 'Kathleen Cleaver'], correctAnswer: 0, explanation: 'Angela Davis\'s firing, imprisonment, and 1972 acquittal made her an international symbol and shaped her later prison-abolition work. Audre Lorde was a poet and essayist, Sonia Sanchez a Black Arts Movement poet, and Kathleen Cleaver a Black Panther Party leader.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-black-power-beyond', part: 7, formSet: 2 },

  // ── aas-contemporary-issues ──
  { question: 'From the late twentieth century to the present, which pattern does the AP course framework emphasize for African American communities?', options: ['A larger Black middle class and political firsts alongside a persistent wealth gap', 'A closing of the racial wealth gap once civil rights laws took full effect', 'A shrinking Black population as immigration from Africa nearly stopped', 'Stalled representation, with no Black candidate winning national office'], correctAnswer: 0, explanation: 'The framework pairs a growing Black middle class and firsts such as the elections of Barack Obama and Kamala Harris with a large racial wealth gap rooted in earlier discrimination. The wealth gap did not close, the Black population grew through immigration, and representation expanded sharply after 1965.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 1, formSet: 1 },
  { question: 'Shirley Chisholm is significant in African American political history because she', options: ['was the first Black woman elected to Congress and helped found the Congressional Black Caucus', 'was the first Black secretary of state and served under President George W. Bush', 'was the first Black American elected vice president, winning in the election of 2020', 'refused induction into the Army in 1967 and said the real enemy was at home'], correctAnswer: 0, explanation: 'Chisholm won election to Congress in 1968 and helped found the Congressional Black Caucus in 1971. Colin Powell was the first Black secretary of state, Kamala Harris the first Black vice president, and Muhammad Ali refused induction in 1967.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 1, formSet: 2 },
  { question: 'Afrofuturism is best described as a movement that', options: ['reimagines Black pasts and envisions Afrocentric futures through science and technology', 'rejects all science fiction as a distraction from present-day political organizing', 'calls for Black Americans to resettle in Africa to build a technologically modern state', 'limits Black art to realistic portraits of everyday life in American cities'], correctAnswer: 0, explanation: 'The framework defines Afrofuturism as reimagining Black pasts and envisioning Afrocentric futures through technology and science, across art, music, film, fashion, literature and architecture. It embraces speculative fiction, is not an emigration program, and is not limited to realism.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 1, formSet: 1 },
  { question: 'Which of the following events happened first?', options: ['Jackie Robinson joins Major League Baseball', 'Shirley Chisholm wins election to Congress', 'Colin Powell becomes secretary of state', 'Kamala Harris is elected vice president'], correctAnswer: 0, explanation: 'Robinson joined the major leagues in 1947, Chisholm was elected in 1968, Powell became secretary of state in 2001 and Harris was elected vice president in 2020.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 7, formSet: 2 },
  { question: 'Black athletes founded the Negro leagues after the Civil War and the Colored Hockey League of the Maritimes in 1895 mainly because', options: ['racial segregation shut them out of white-run leagues', 'federal law required a separate league for each race', 'white leagues played too few games each season', 'they wished to avoid competing against white athletes'], correctAnswer: 0, explanation: 'Segregation in sports barred Black athletes from white-run leagues, so they built their own. No federal law required separate leagues, season length was not the cause, and Black athletes such as Oliver Lewis competed in integrated events like the first Kentucky Derby.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 2, formSet: 1 },
  { question: 'Black physicians founded the National Medical Association because', options: ['they were barred from the American Medical Association', 'federal law required separate medical associations for each race', 'the Americans with Disabilities Act called for new medical groups', 'HBCU medical schools refused to admit students from the North'], correctAnswer: 0, explanation: 'Exclusion from the American Medical Association led Black doctors to build their own professional association, as well as medical schools such as Meharry, Howard and Morehouse. No federal law required separate associations, and the ADA came much later, in 1990.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 2, formSet: 2 },
  { question: 'Between 1970 and 2006 the number of Black elected officials in the United States grew from about 1,500 to about 9,000. This growth most directly reflects', options: ['the Voting Rights Act of 1965', 'the founding of the Negro leagues', 'the ratification of the Nineteenth Amendment', 'the Supreme Court\'s ruling in Dred Scott v. Sandford'], correctAnswer: 0, explanation: 'By barring state and local voting laws that discriminated by race, the Voting Rights Act expanded Black voting power and representation about sixfold. The Negro leagues concern sports, the Nineteenth Amendment concerns woman suffrage, and Dred Scott denied Black citizenship in 1857.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 3, formSet: 1 },
  { question: 'Colin Powell and Condoleezza Rice are significant in African American history because they', options: ['were the first Black man and first Black woman to serve as secretary of state', 'became the first Black Americans elected president and vice president', 'founded the Congressional Black Caucus in Congress in 1971', 'won Olympic gold medals at the 1936 Games in Berlin'], correctAnswer: 0, explanation: 'Powell became the first Black secretary of state in 2001 under George W. Bush, and Rice succeeded him as the first Black woman in that post. Obama and Harris were the first Black president and vice president, Chisholm helped found the CBC, and Jesse Owens won four golds in 1936.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 3, formSet: 2 },
  { question: 'In 2016 the median wealth of Black families was about one-tenth that of white families. Which explanation does the course framework emphasize?', options: ['Earlier discrimination in housing and jobs limited what could pass down across generations', 'Black families earned higher incomes but chose to save less than white families', 'The gap first appeared after 2000 because of new federal tax rules on inheritance', 'Most Black families lived in rural areas where homes and land held little value'], correctAnswer: 0, explanation: 'EK 4.15.A.1 ties the gap to discrimination in housing and employment early in the twentieth century, which limited the generational wealth Black families could build. Black median incomes have been lower, the gap long predates 2000, and most Black Americans live in urban areas.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 4, formSet: 1 },
  { question: 'Historians link 1930s federal housing policy to today\'s racial wealth gap mainly because', options: ['mortgage maps and rules steered lending away from Black neighborhoods', 'federal agencies built most new housing for Black families in the 1930s', 'the policies required every bank to lend equally in all neighborhoods', 'home values in redlined areas rose faster than in other neighborhoods'], correctAnswer: 0, explanation: 'HOLC maps graded Black neighborhoods as hazardous and FHA rules steered insured lending to white areas, limiting Black homeownership, the main source of family wealth. The policies did not build housing for Black families, did not require equal lending, and did not make redlined home values rise faster.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 4, formSet: 2 },
  { question: 'According to the course framework, hip-hop emerged in the 1970s from', options: ['young Black and Latino community members in the Bronx', 'Southern gospel choirs using electric guitars', 'Hollywood studios scoring films about Black life', 'a federal arts program in Chicago\'s public schools'], correctAnswer: 0, explanation: 'The framework describes hip-hop as a culture born from the collaboration of young Black and Latino community members in the Bronx in the 1970s, with DJing, rapping, breakdancing and graffiti. Gospel with electric guitars points to the roots of rock and roll.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 5, formSet: 1 },
  { question: 'According to the course framework, the near doubling of the Black immigrant population in the United States since 2000 was driven mainly by arrivals from', options: ['Africa and the Caribbean', 'Europe and Canada', 'South Asia', 'the Pacific Islands'], correctAnswer: 0, explanation: 'EK 4.16.A.2 attributes the growth mainly to immigrants from Africa and the Caribbean, which also helped make Black communities more diverse in ancestry and identity.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 5, formSet: 2 },
  { question: 'Oscar Micheaux, who produced nearly 50 films between the 1920s and 1940s, is significant because he', options: ['countered racist screen images with realistic, complex Black characters', 'created the television dance program Soul Train in 1971', 'wrote the play Fences, which reached Broadway in 1987', 'starred in the 1990s television series The Fresh Prince of Bel-Air'], correctAnswer: 0, explanation: 'Micheaux gave all-Black casts a range of roles that challenged the racist depictions of early cinema and paved the way for later Black directors and producers. Don Cornelius created Soul Train, August Wilson wrote Fences, and The Fresh Prince starred Will Smith.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 5, formSet: 1 },
  { question: 'When Tommie Smith and John Carlos raised their fists on the medal stand at the 1968 Olympics, they intended mainly to', options: ['protest racial discrimination in solidarity with the Black Freedom movement', 'celebrate the U.S. Olympic Committee\'s new policy of full integration', 'protest the military draft for the Vietnam War, as Muhammad Ali had done', 'mark the first Olympic Games in which Black athletes had been allowed'], correctAnswer: 0, explanation: 'The raised Black power fist was a nonviolent protest against racial discrimination and a sign of solidarity with the Black Freedom movement. It was not a celebration of official policy, not a draft protest, and Black athletes such as Jesse Owens had competed in the Olympics decades earlier.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 6, formSet: 2 },
  { question: 'Kehinde Wiley\'s 2018 portrait of Barack Obama surrounds him with flowers associated with Chicago, Hawaii and Kenya. A historian would most likely read these symbols as', options: ['a visual biography of the places that shaped Obama\'s life', 'a record of the states that voted for Obama in 2008', 'a list of the official flowers of the White House gardens', 'evidence that the portrait was painted outdoors in summer'], correctAnswer: 0, explanation: 'Chrysanthemums for Chicago, jasmine for Hawaii and African blue lilies for his father\'s Kenya trace Obama\'s personal history. They do not map election results, White House gardens or the setting where the painting was made.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 6, formSet: 1 },
  { question: 'In 2016 Colin Kaepernick and other NFL players began kneeling during the national anthem in order to', options: ['protest police brutality', 'honor veterans of the Vietnam War', 'support new team ownership rules', 'celebrate the Voting Rights Act'], correctAnswer: 0, explanation: 'The framework (EK 4.19.B.4) describes the kneeling as a peaceful protest against police brutality that spread to other sports and drew national attention to the issue.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-contemporary-issues', part: 7, formSet: 1 },

  // ── aas-movements-debates ──
  { question: 'In the 1850s Martin Delany and Frederick Douglass disagreed mainly over whether Black Americans should', options: ['support Garrison\'s moral suasion or join the new Liberty Party', 'seek a nation of their own abroad or claim citizenship at home', 'accept gradual emancipation or demand an immediate end to slavery', 'pursue literacy and schooling or prepare for armed slave revolts'], correctAnswer: 1, explanation: 'Delany promoted emigration and Black nationalism, while Douglass insisted that Black Americans claim equal rights in the United States, an early form of the integration-versus-separatism debate. Both men were immediatists, and their central dispute was not over Garrison, schooling, or revolt.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 1, formSet: 1 },
  { question: 'Which pairing correctly matches each leader with the strategy he championed between 1895 and 1915?', options: ['Washington: liberal arts and protest; Du Bois: vocational training and patience', 'Washington: vocational uplift; Du Bois: liberal education and agitation', 'Washington: federal lawsuits; Du Bois: building Black-owned banks and stores', 'Washington: emigration to Africa; Du Bois: armed self-defense in the South'], correctAnswer: 1, explanation: 'Washington urged industrial education and economic progress while deferring political demands, and Du Bois called for higher education for a "Talented Tenth" and open agitation for civil and political rights. Swapping their programs reverses the two men, and neither man made emigration, armed self-defense, or lawsuits his signature strategy.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 1, formSet: 2 },
  { question: 'Which development is the clearest example of Pan-Africanism?', options: ['The Supreme Court ruling in Brown v. Board of Education', 'Booker T. Washington\'s Atlanta Exposition address', 'Du Bois\'s congresses uniting the diaspora worldwide', 'The passage of the Civil Rights Act of 1964 by Congress'], correctAnswer: 2, explanation: 'Pan-Africanism links people of African descent across the globe in a shared political project, as Du Bois\'s Pan-African Congresses (1900–1945) did. Brown, the Atlanta address, and the Civil Rights Act were all focused on rights and conditions within the United States.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 1, formSet: 1 },
  { question: 'In 1964 Malcolm X urged activists to expand their struggle "from civil rights to human rights." This shift meant', options: ['abandoning all political goals in favor of religious separatism', 'working only through Congress and the federal courts for change', 'limiting the movement\'s demands to the desegregation of schools', 'bringing Black Americans\' grievances before world bodies like the UN'], correctAnswer: 3, explanation: 'Framing racism as a human rights violation let activists appeal beyond the U.S. government to international forums and to newly independent nations. Malcolm X did not abandon politics, he criticized reliance on Congress and the courts, and he broadened rather than narrowed the movement\'s demands.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 1, formSet: 2 },
  { question: 'The Combahee River Collective Statement (1977) is regarded as a foundational Black feminist document because it', options: ['argued that Black women face interlocking systems of oppression', 'called for Black women to leave politics to male leaders', 'urged Black feminists to merge into white-led organizations', 'focused only on winning equal pay through labor unions'], correctAnswer: 0, explanation: 'The Boston collective argued that racial, sexual, heterosexual, and class oppression are interlocking and must be fought together, defining identity politics from its members\' own standpoint. It insisted on Black women\'s leadership, criticized white-led feminism\'s blind spots, and was far broader than a pay campaign.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 2, formSet: 1 },
  { question: 'Black Power\'s ties in the late 1960s and 1970s to leaders such as Ghana\'s Kwame Nkrumah belong to which long-running strand of Black thought?', options: ['Accommodationism', 'Gradualism', 'Pan-Africanism', 'Moral suasion'], correctAnswer: 2, explanation: 'Pan-Africanism, running from Du Bois and Garvey through Nkrumah, links the freedom of Black Americans to Africa and the wider diaspora. Accommodationism was Washington\'s approach, gradualism and moral suasion were nineteenth-century antislavery strategies.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 2, formSet: 2 },
  { question: 'At the 1919 Pan-African Congress in Paris, W. E. B. Du Bois and other delegates', options: ['founded the Universal Negro Improvement Association', 'organized a return of Black American veterans to Africa', 'signed a treaty creating independent states in Africa', 'petitioned the Versailles peace conference on behalf of Africans'], correctAnswer: 3, explanation: 'Meeting alongside the Versailles peace talks, the congress petitioned the powers to protect the rights of Africans in colonial territories. Garvey founded the UNIA in Jamaica in 1914, the congress did not organize emigration, and it had no power to create states.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 3, formSet: 1 },
  { question: 'The 1955 Bandung Conference of newly independent Asian and African nations influenced African American activists by', options: ['encouraging them to see their cause as part of a global anticolonial struggle', 'persuading them to drop civil rights demands until the Cold War had ended', 'convincing them to give up nonviolence for armed revolt', 'leading Congress to pass the first federal civil rights law that same year'], correctAnswer: 0, explanation: 'Bandung\'s Asian-African solidarity helped activists reframe civil rights as one front in a global struggle against colonialism and racism. It did not counsel waiting, its principles stressed peaceful coexistence rather than armed revolt, and the first modern federal civil rights law came in 1957.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 3, formSet: 2 },
  { question: 'Which present-day argument most directly continues the older debate between integration and separatism?', options: ['Whether the federal government should regulate interstate commerce', 'Whether presidential elections should be decided by popular vote', 'Whether to build Black institutions or join mainstream ones', 'Whether schools should teach world history before American history'], correctAnswer: 2, explanation: 'Choosing between building up Black institutions and pursuing inclusion in majority-white ones echoes Douglass and Delany, the NAACP and the Nation of Islam, and King and Malcolm X. The other questions are general policy debates without that lineage.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 4, formSet: 1 },
  { question: 'W. E. B. Du Bois wrote in 1926 that "all Art is propaganda," while Langston Hughes urged Black artists to express themselves "without fear or shame." Their disagreement was mainly over', options: ['whether creative work should serve the struggle for justice or the artist\'s vision', 'whether Black artists should move to Paris or stay and work in Harlem', 'whether African themes belonged in American poetry at all', 'whether white patrons should be allowed to buy Black art'], correctAnswer: 0, explanation: 'Du Bois wanted Black art to serve the fight for justice, while Hughes defended the artist\'s freedom to portray Black life as it was. Neither essay argued about emigration to Paris, rejected African themes, or tried to bar white patrons.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 4, formSet: 2 },
  { question: 'Kimberlé Crenshaw introduced the term "intersectionality" in a 1989 law review article mainly to explain', options: ['why antidiscrimination law failed Black women facing combined race and sex bias', 'how Black men and Black women experienced identical forms of discrimination', 'why courts should stop hearing employment cases involving race altogether', 'how class alone accounted for the inequalities Black workers experienced'], correctAnswer: 0, explanation: 'Crenshaw showed that courts treated race and sex discrimination as separate categories, so Black women whose experience combined both fell through the gaps. Her point was that their experience differs from Black men\'s, she sought stronger rather than fewer remedies, and she rejected single-factor explanations such as class alone.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 5, formSet: 1 },
  { question: 'Which statement best describes a continuity in arguments for armed self-defense from Ida B. Wells (1892) to the Deacons for Defense and Justice (1964–65)?', options: ['Self-protection was needed where the law failed to protect Black people', 'Armed revolt was needed to overthrow the federal and state governments', 'Nonviolence had already won full legal equality across the South', 'Self-defense required emigration to Africa before it could succeed'], correctAnswer: 0, explanation: 'Wells urged armed protection "which the law refuses to give," and the Deacons guarded Black communities and civil rights workers when police would not. Neither sought to overthrow the government, neither claimed equality had been won, and neither tied self-defense to emigration.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 5, formSet: 2 },
  { question: 'Which statement describes a CONTINUITY in African American political thought from Douglass and Delany in the 1850s to King and Malcolm X in the 1960s?', options: ['Leaders all agreed that emigration offered the only path to freedom.', 'Leaders relied on federal courts as the sole means of change.', 'Leaders accepted gradual change and avoided public protest.', 'Leaders debated integration against building separate Black power.'], correctAnswer: 3, explanation: 'In both eras, leaders argued over whether to seek full inclusion in American society or to build separate institutions and nationhood. Douglass and King rejected emigration, neither era relied on courts alone, and all four leaders engaged in public agitation.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 5, formSet: 1 },
  { question: 'Read the excerpt from the Combahee River Collective Statement (1977): "We are actively committed to struggling against racial, sexual, heterosexual, and class oppression . . . based upon the fact that the major systems of oppression are interlocking." The authors\' central argument is that', options: ['these forms of oppression are linked and must be challenged together', 'racial oppression should be fought first and the others addressed later', 'class struggle alone would end every other form of oppression', 'sexual and racial oppression affect all women in identical ways'], correctAnswer: 0, explanation: 'The collective held that race, sex, sexuality, and class oppression reinforce one another, so a politics addressing only one would fail Black women. The statement explicitly rejects ranking the struggles, reducing them to class, or assuming all women share one experience.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 6, formSet: 2 },
  { question: 'Crenshaw\'s "Demarginalizing the Intersection of Race and Sex" (1989) first appeared in a law journal. That origin helps explain why the concept was first framed around', options: ['the poetry of the Black Arts Movement', 'statistics on the Great Migration', 'court cases dismissing Black women\'s claims', 'speeches from the March on Washington'], correctAnswer: 2, explanation: 'As a legal scholar writing for a law audience, Crenshaw built her argument on discrimination cases in which courts would not recognize Black women\'s combined claims. Poetry, migration data, and 1963 speeches were not the evidence of a law review article.', difficulty: 'medium', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 6, formSet: 1 },
  { question: 'Audre Lorde wrote that "the master\'s tools will never dismantle the master\'s house" (Sister Outsider, 1984). Her point was that', options: ['movements must master the legal system before attempting any reform', 'Black women should build homes and businesses before engaging in politics', 'only working within established institutions can produce lasting change', 'movements that copy the dominant system\'s exclusions cannot transform it'], correctAnswer: 3, explanation: 'Lorde warned feminists and others that reproducing the hierarchies and silences of the dominant culture, including ignoring differences of race and sexuality, could not bring genuine change. Her metaphor rejects relying on the existing system\'s methods, the opposite of the other three claims.', difficulty: 'hard', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 7, formSet: 2 },
  { question: 'Which nineteenth-century figure is most associated with emigration and early Black nationalism, in contrast to Frederick Douglass\'s integrationism?', options: ['Martin Delany', 'Booker T. Washington', 'Prince Hall', 'Richard Allen'], correctAnswer: 0, explanation: 'Martin Delany argued that Black Americans should build a nation of their own abroad and is often called a father of Black nationalism. Washington led Tuskegee and urged accommodation, Prince Hall founded a Black Masonic lodge, and Richard Allen founded the AME Church.', difficulty: 'easy', domain: 'movements-debates', topicSlug: 'aas-movements-debates', part: 7, formSet: 1 },
]

export function generateExitQuiz(count = 10, topicSlug?: string): { id: string; question: string; options: string[]; correctIndex: number; explanation: string; category: string }[] {
  let pool: AASQuestion[] = aasQuestionPool
  if (topicSlug) pool = relevantPool(pool, topicSlug)
  return shuffleArray(pool).slice(0, count).map((q, i) => ({
    id: `${q.topicSlug}-q${i}`,
    question: q.question,
    options: q.options,
    correctIndex: q.correctAnswer,
    explanation: q.explanation,
    category: q.domain,
    topicSlug: q.topicSlug,
    partNumber: q.part,
  }))
}
